export const PRODUCT = {

recruitment: {
  packages: ["educationcloud"],
  name: "Recruitment",
  icon: "\u{1F4E3}",
  color: "#3b82f6",
  description: "Recruitment in Education Cloud manages prospective learner engagement from initial identification through application readiness. It represents unengaged suspects as Leads and interested prospects as Person Accounts, while the Education Portal supports requests for information and the Student Recruitment Agent automates questions, recruiter-contact requests, and campus tour registration. Campaigns, Actionable Lists, staff assignments, inquiry flows, and recruitment communications help institutions organize and nurture prospect relationships. Recruitment funnel dashboards guide prioritization, and qualified prospects move into the admissions application process.",
  components: [
    {id:"prospect-management",name:"Prospect Management",icon:"\u{1F465}",desc:"Prospect Management in Education Cloud distinguishes suspects who have not indicated interest from prospects who have engaged with the institution. Suspects are stored as Lead records, while interested individuals are represented by Person Accounts that provide recruiting teams with a more complete person record. Recruiters can manage requests for information, appointments, prospect details, and engagement activities from the Recruitment & Admissions app. Directors can create prospect lists, assign them to staff, and use recruitment analytics to monitor pipeline health.",tags:["Lead","ContactProfile"],docs:["Education Cloud uses the Lead and Person Account objects to represent different stages of prospective learner engagement. A person who has not indicated interest is modeled as a suspect with a Lead record. When that person signals interest, the Lead is converted to a Person Account so recruiters can deliver more personalized engagement. Person Accounts combine account and contact information into a single record and provide the person data used across Education Cloud.","The Education Portal lets prospective learners request information, apply for admission, upload admissions documents, and schedule appointments with support staff. Inquiry management flows support several types of engagement: EDU Cloud: Inquiry: Sign Up for Information processes requests for ongoing communications, EDU Cloud: Inquiry: Connect With Us creates a contact request, and EDU Cloud: Inquiry: Submit an Inquiry Form creates a case associated with an educational info request. These flows use EDU Admissions: Process Person Account and EDU Cloud: Inquiry: Academic Interest Processing to consolidate person and academic-interest processing.","The Recruitment & Admissions app supports prospect work through Educational Info Requests, Actionable Lists, tasks, appointments, and analytics. Actionable Lists can contain prospects and be assigned to staff for targeted marketing, while the prospect record page can include the EDUAdmissionsPersonProfileCard, Timeline, Action Launcher, Actionable List Engagement, and request-for-information components. Prospect Engagement Score (Education Cloud) can predict the likelihood that a prospective learner will enroll based on current engagement. The Recruitment Insights dashboard shows pipeline health, request-for-information status, and lead sources so recruiters can prioritize follow-up."],docUrl:"https://developer.salesforce.com/docs/platform/data-models/guide/recruitment-and-admissions.html",connections:[{"planet":"admissions","desc":"Qualified prospects submit applications"},{"planet":"records","desc":"Prospect data flows into person records"}]},
    {id:"campaign-management",name:"Campaign Management",icon:"\u{1F4E8}",desc:"Campaign Management in Education Cloud organizes recruitment outreach and associates it with prospective learners. Campaign records capture the campaign name, type, status, dates, and lead count, while CampaignMember records connect campaigns with Lead or Contact records and track member status. Recruitment campaigns can support targeted marketing and campus tour registration. Marketing Cloud Engagement for Industries can synchronize Education Cloud CRM data with Marketing Cloud for email campaigns.",tags:["Campaign","CampaignMember"],docs:["Recruitment teams can use campaigns alongside prospect lists and targeted outreach. Campaign records provide identifying, classification, status, date, and lead-count information, while CampaignMember records relate a campaign to a Lead or Contact. This structure supports tracking the people associated with an outreach effort and their campaign-member status. The Recruitment & Admissions app also provides Actionable Lists that staff can use for targeted marketing.","The Student Recruitment Agent uses Campaign records for campus tour registration. Its Campus Tours, Visits, and Events Registration subagent includes Get Campus Tour Campaigns and Create Campus Tour Registration. During setup, Recruitment Event is added as a value for the Type field on Campaign, and a campaign sharing rule can share campaigns of that type with portal roles as Read Only. This configuration makes the relevant campus tour campaigns available to the agent.","For email outreach, Marketing Cloud Engagement for Industries synchronizes Education Cloud CRM data with Marketing Cloud to create campaigns. Documented use cases include application deadline reminders, recruiting appointment details, and other outreach. The EDU Cloud: Inquiry: Sign Up for Information flow can collect a prospect's request for regular updates and communications, and the collected data can be used to enroll the prospect in a Marketing Cloud journey through Marketing Cloud Connect."],connections:[{"planet":"analytics","desc":"Campaign metrics feed recruitment dashboards"}]},
    {id:"recruitment-events",name:"Recruitment Events",icon:"\u{1F3AA}",desc:"Recruitment Events in Education Cloud support recruiters who represent their institutions at college fairs, on-campus events, conferences, and other recruitment events. The Student Recruitment Agent can provide information about campus tours, visits, and events and help users register. Campus tour registration uses Campaign records configured with the Recruitment Event type. Event registration is handled by the agent's Create Campus Tour Registration action rather than by the Education Portal's documented request-for-information features.",tags:["Campaign","CampaignMember"],docs:["Recruiters use recruitment events to represent the institution and support prospective students throughout the admissions process. Their responsibilities include participating in college fairs, on-campus events, conferences, and recruitment events, and communicating application requirements and deadlines. Education Cloud provides the Recruitment & Admissions app and recruiter console to help recruiters manage related tasks, upcoming events, and recruitment analytics.","The Student Recruitment Agent includes the Campus Tours, Visits, and Events Registration subagent. This subagent assists users with registration for campus tours, campus visits, or campus events through the Create Campus Tour Registration action. It also uses Get Campus Tour Campaigns to retrieve relevant Campaign records. The agent can provide prospective students with campus information in addition to information about learning programs, support programs, and admissions processes.","To configure campus tour campaigns for the Student Recruitment Agent, add Recruitment Event as a Campaign Type value. A Campaign sharing rule can then share Campaign records whose Type equals Recruitment Event with the appropriate portal roles using Read Only access. For unauthenticated users, clone and configure EDU Admissions: Get Planned Campaigns and EDU Admissions: Create Campus Tour Registration, along with the related person-account processing flow. These flows run in System Context Without Sharing - Access All Data only when that configuration aligns with the institution's security model."],connections:[{"planet":"experience","desc":"Event registration through the prospect portal"}]},
    {id:"recruitment-communications",name:"Recruitment Communications",icon:"\u{1F4EC}",desc:"Recruitment Communications in Education Cloud help prospects request information, subscribe to updates, ask questions, and connect with institutional staff. Inquiry management flows create and relate person, academic-interest, contact-request, educational-info-request, and case data according to the type of inquiry. The Student Recruitment Agent can answer questions grounded in knowledge articles and create an Academic Interest when a prospective student requests recruiter contact for a specific learning program. Marketing Cloud Engagement for Industries supports email outreach based on synchronized Education Cloud CRM data.",tags:["ContactPointEmail","ContactPointPhone"],docs:["Education Cloud provides separate inquiry flows for different communication needs. EDU Cloud: Inquiry: Sign Up for Information processes requests for regular updates and communications, EDU Cloud: Inquiry: Connect With Us creates a contact request, and EDU Cloud: Inquiry: Submit an Inquiry Form creates a case associated with an educational info request. The flows use shared subflows to process Person Accounts and Academic Interest records. Inquiry Flexcards can expose these flows in the Education Portal, or Lightning Out can embed them in a third-party website.","The Student Recruitment Agent can answer questions about learning programs, support programs, application processes, and campus information. The Admissions and Enrollments FAQ subagent uses Answer Questions with Knowledge, so institutions create knowledge articles to ground its responses. The Request for Information subagent uses Create Academic Interest when a user explicitly requests contact from a recruiter and indicates interest in a specific learning program. An escalation subagent can redirect unanswered conversations to a human representative, and the Create Inquiry action can create a case, an educational info request, and an academic interest.","Marketing Cloud Engagement for Industries synchronizes Education Cloud CRM data with Marketing Cloud for email campaigns. Documented recruitment use cases include application deadline reminders and recruiting appointment details. The information collected by EDU Cloud: Inquiry: Sign Up for Information can be used to enroll a prospect in a Marketing Cloud journey through Marketing Cloud Connect. Recruiters can also respond to and manage prospective students' requests for information from the Recruitment & Admissions consoles."],connections:[{"planet":"agentforce","desc":"Recruitment agent automates outreach sequences"}]},
    {id:"territory-management",name:"Territory Management",icon:"\u{1F5FA}",desc:"Territory Management in Education Cloud supports the operational assignment and distribution of prospects among recruitment staff. Admissions directors can create prospect lists and assign them to recruiters, while Actionable Lists provide portfolios that staff can use for targeted engagement. Business Rules Engine can support custom routing logic based on prospect attributes from an interest form. Recruitment dashboards help directors and recruiters evaluate pipeline distribution and focus staff effort.",tags:["Lead"],docs:["The Recruitment & Admissions app provides Actionable Lists for organizing prospect work. Directors can create lists of prospects and assign them to recruiters, and the Director Console provides a central page for recruitment and admissions analytics and actionable-list work. Actionable List Engagement, Actionable Segmentation, and Actionable List Member support lists built from multiple objects, staff collaboration, and actions within a list. A documented use case is creating a portfolio of prospects for relationship officers.","Institutions can use Business Rules Engine for custom prospect-routing logic. The documented examples include routing prospects to the right counselor based on attributes from an interests form and routing learners to the right staff member for application follow-up. Business Rules Engine uses custom rule sets that can be invoked from OmniScripts and Flow Builder, allowing business logic to change without changing the surrounding automation. The routing rules and assignment criteria are configured according to the institution's processes.","Education Analytics provides recruitment views for monitoring assigned work and pipeline performance. The Recruitment Insights dashboard shows candidates by stage, requests for information, and lead sources, while Admissions and Recruitment Insights provides directors with an overall summary of the recruitment and admissions pipeline. These dashboards help staff identify pipeline conditions and prioritize prospects. Directors can also track progress toward institutional goals through KPI reports."],connections:[{"planet":"analytics","desc":"Territory performance feeds recruitment analytics"}]}
  ],
  dataFlow: ["Import unengaged suspects as Lead records and capture their source and status.","Capture requests for information through the Education Portal, and use the Student Recruitment Agent for automated questions, recruiter-contact requests, and campus tour registration.","Convert interested suspects into Person Accounts and retain related ContactProfile data as part of the person record.","Organize prospects with campaigns and Actionable Lists, then assign outreach work to recruitment staff.","Review recruitment funnel dashboards and prospect engagement predictions to prioritize follow-up.","Advance qualified prospects into admissions applications."],
  connections: [{"planet":"admissions","desc":"Qualified prospects move to applications"},{"planet":"records","desc":"Prospect data creates person records"},{"planet":"agentforce","desc":"AI recruitment agent automates outreach"},{"planet":"experience","desc":"Prospect portal for inquiry and events"},{"planet":"analytics","desc":"Recruitment funnel dashboards"}]
},

admissions: {
  packages: ["educationcloud"],
  name: "Admissions",
  icon: "\u{1F4CB}",
  color: "#6366f1",
  description: "Admissions in Education Cloud manages applications that originate from recruited prospects and connects them to applicant information stored on Person Accounts and related admissions records. Through the Education Portal, applicants can start and manage applications, complete tasks, upload documents, track status, and receive answers about admissions or financial aid from an AI agent. Admissions staff verify materials, conduct and score reviews, record decisions, and coordinate related application fees and financial aid packaging. After an admit decision, staff can enroll the learner in a Learning Program.",
  components: [
    {id:"application-management",name:"Application Management",icon:"\u{1F4C4}",desc:"Application Management coordinates the creation, submission, and ongoing management of admissions applications in Education Cloud. Applicants use the Education Portal to start applications, complete application stages and tasks, review their information, and submit or withdraw applications. Staff use related admissions records, automation, and configurable Omnistudio components to manage applications from intake through review and decision. Application records connect the applicant’s person record with the applicable Learning Program, academic term, and application timeline.",tags:["IndividualApplication","Applicant"],docs:["Education Cloud supports single-stage and multiple-stage applications. A single-stage application is completed and submitted at once, while a multiple-stage application lets applicants complete stages at different times and in any order. Application Stage Definition records represent the stages, and Application Render Method records identify the Omniscript or Flexcard used to collect or display information. Application Render Method Assignment records connect the render methods to their corresponding stages.","An Action Plan Template defines the structure of an application, with Individual Application Tasks representing its stages. The template is assigned to a Program Term Application Timeline record, which connects the Learning Program, Academic Term, Application Timeline, and application structure. Active Program Term Application Timeline records determine which programs and timelines are available in the New Application window. When an applicant starts an application, Education Cloud creates the related Preliminary Application Reference and Individual Application records.","Applicants can use the Education Portal to list existing applications, view statuses and details, and start new applications. Institutions can configure options that let applicants edit and view tasks, confirm information, provide a digital signature, submit completed applications, cancel unsubmitted applications, or withdraw submitted applications. After submission, applicants can view application task details but can no longer edit them. Related financial processes can account for application fees and provide information about financial aid applications, awards, required documents, and financial aid packages."],docUrl:"https://developer.salesforce.com/docs/platform/data-models/guide/recruitment-and-admissions.html",connections:[{"planet":"recruitment","desc":"Applications originate from recruited prospects"},{"planet":"enrollment","desc":"Admitted students proceed to enrollment"}]},
    {id:"document-tracking",name:"Document Tracking",icon:"\u{1F4CE}",desc:"Document Tracking manages the files and supporting materials required for an admissions application in Education Cloud. Document Checklist Item records associate submitted materials with an application or another parent record and track whether each item is new, accepted, rejected, or waived. Applicant uploads are stored as Salesforce Files and are available from the Individual Application record and Document Checklist Item object. Admissions staff can verify, preview, add, update, or delete materials according to their permissions and document-management policies.",tags:["DocumentChecklistItem"],docs:["Applicants can upload essays, transcripts, recommendation letters, and other required materials through the application experience. Education Cloud automatically saves applicant uploads as Salesforce Files and associates them with Document Checklist Item records. Each document checklist item must use a unique Salesforce File, although the same file can also be related to other Salesforce records. Supported files include PDF, common Microsoft Office, image, text, and rich-text formats, subject to documented preview limitations.","During verification, staff review each submitted file or data item and set its approval status. Approving or rejecting a document updates the Status on its Document Checklist Item record, and staff can also waive a requirement or edit its status later. Education Cloud presents Document Checklist Item statuses in the application components as Ready for Processing, Waived, Approved, Rejected, or Needs Attention, depending on the user and underlying status. Staff can also add a last-minute document directly to an Individual Application record.","Administrators enable Checklist Items with Attachments in Document Checklist Settings to support checklist items with uploaded files and document deletion workflows. Deleting an Individual Application doesn't automatically delete its related tasks, Document Checklist Item records, or files, so institutions must plan for the full document lifecycle. Education Cloud provides basic document management but doesn't provide specialized admissions-document archival automation. Institutions can also use Document Checklist, Document Generation, Intelligent Document Reader, and supported external storage with Amazon S3 as appropriate."],connections:[]},
    {id:"application-review",name:"Application Review",icon:"\u{1F50D}",desc:"Application Review supports intake verification, assigned reviews, rubric-based scoring, and admissions recommendations in Education Cloud. Admissions staff first confirm that required data and documents are complete and acceptable, after which reviewers assess the application. Review records can be assigned to queues or individual reviewers and displayed in the Admissions Console or Reviewer Console. Configurable flows can move applications through Processing, In Review, and Ready for Decision statuses.",tags:["IndividualApplication"],docs:["Verification and review are separate steps in the admissions process. During verification, staff inspect submitted data and documents, identify records that still need verification, and approve, reject, or waive requirements. When all required information is available, the application can proceed to review. The application review page organizes materials in a navigable, scrollable view and can display supported documents in a built-in viewer.","Reviewers assess assigned applications and submit a recommendation such as Pending, Admit, Admit with Conditions, or Deny. They can enter comments and, when a rubric is configured, select ratings for each criterion before reviewing the calculated score. After a reviewer submits a recommendation, its contents become view-only. Application Review records can be assigned from a queue to reviewer users for scoring.","Education Cloud provides flow templates to automate review processing. Admissions: Initiate Application Reviews invokes the review-creation process when an Individual Application enters In Review, while Application Review updates an application to Ready for Decision when all reviews are complete. Rubrics use Discovery Framework assessment questions, Omniscripts, Application Render Method records, Application Stage Definition records, and Action Plan Templates. Institutions can use one rubric for an application or customize the objects and flows to use different rubrics for different review stages."],connections:[]},
    {id:"admissions-decisions",name:"Admissions Decisions",icon:"\u{2705}",desc:"Admissions Decisions records and releases the final outcome of an application in Education Cloud. Admissions staff review completed Application Review records and create an Application Decision from the related Individual Application. Decision options documented for the final process include Admit, Enroll, Waitlist, Deny, and Cancelled. Decision sharing to portal users is controlled by the dates on the Application Timeline and can be disabled for future and previously shared decisions.",tags:["IndividualApplication","Applicant"],docs:["After reviewers submit their recommendations, authorized admissions staff make the final decision from the Individual Application record. Staff review the related Application Reviews, create an Application Decision, select the application recommendation, and save any other relevant information. Application Decision represents the publicly released decision for an application to an institution. Education Cloud also provides an Application Decision record page that can show details, related lists, and activity.","Application Decision records are automatically shared with Experience Cloud users according to the Decision Release Date and Early Application Release Date on the Application Timeline. A future Decision Release Date delays sharing until that date, while a current or past date shares the decision immediately. If no Decision Release Date is provided, the decision isn't shared automatically. Rolling admissions can use a current or past release date, or align the Application Open Date and Decision Release Date so decisions are shared as they are created within the application period.","Application Decision Creation can create an Application Decision record and assign it to the Application_Decisions queue when an application is Ready for Decision. Another application-decision flow updates the Individual Application when the Application Decision field has a value. Institutions can disable automatic decision sharing from the Education Cloud setup settings. After an admit decision, staff can use Enroll Admitted Student on the Individual Application record to enroll the learner in a Learning Program, Learning Program Plan, and Academic Term."],connections:[{"planet":"financials","desc":"Admission triggers financial aid packaging"}]},
    {id:"preliminary-applications",name:"Preliminary Applications",icon:"\u{1F4DD}",desc:"Preliminary Applications preserve applications that are still in progress so applicants can return and finish them later. The Preliminary Application Reference record captures the initial application context before submission. It works with Program Term Application Timeline data to determine the available application type, Academic Term, and Learning Program selections. Education Cloud can create preliminary applications for one or multiple programs from the New Application window.",tags:["PreliminaryApplicationRef"],docs:["The Education Portal Application List page uses the New Application component to start an application. Its available choices are filtered from qualified Program Term Application Timeline records whose related Academic Term and Learning Program are active and whose Application Timeline is open. In Self mode, application details are based on the running user's contact information. In Proxy mode, a user can apply for themselves or on behalf of another person represented by a related contact.","The New Application window can be configured to create a preliminary application for one program or preliminary applications for multiple programs. When the applicant submits the New Application window, Education Cloud automatically creates a Preliminary Application Record and an Individual Application record. The Preliminary Application Reference remains the record for an application in progress, while the Individual Application supports the broader admissions process. Application Category values must be kept consistent between Preliminary Application Reference and Individual Application for application records to set final decision dates properly.","Applicants can manage an unsubmitted application before final submission. Institutions can allow applicants to edit and view application tasks, cancel an unsubmitted application, and choose whether canceled or withdrawn applications appear in the application list. After submission, the application status updates automatically and the applicant can view, but not edit, completed task details. A submitted application can also be withdrawn when that option is enabled."],connections:[{"planet":"recruitment","desc":"Preliminary apps bridge recruitment and admissions"}]},
    {id:"admissions-console",name:"Admissions Console",icon:"\u{1F5A5}",desc:"Admissions Console provides admissions officers with a centralized home page for admissions data, assigned reviews, tasks, and events in Education Cloud. It combines high-level pipeline insights with operational lists such as applications that are ready for a decision and the current user's reviews. Admissions officers can use the console to identify incomplete applications, monitor review progress, and take the next required action. The Recruitment & Admissions app can present a different home page, including the Reviewer Console, according to the user's role and access.",tags:["IndividualApplication"],docs:["The Admissions Console is designed for admissions officers with broad access to Education Cloud. It can show application volume, review status, admissions efficiency, incomplete applications, and applications ready for a decision. Lists provide direct access to applications that need decisions or review, while task and event components show current and upcoming work. The Reviewer Console provides a more focused experience for users who conduct assigned application reviews.","Administrators create the Admissions Console home page in Lightning App Builder and assign it to the Recruitment & Admissions app and selected profiles. The documented layout uses the Education Analytics Dashboard component with Recruitment and Admissions Insights, a Ready for Decision list for Individual Application, and a My Reviews list for Application Review. Today's Tasks and a My Upcoming Events list can be placed in the side column. Education Analytics must be configured before its dashboard can be selected.","The broader Recruitment & Admissions app supports applications, tasks, appointments, Educational Info Requests, actionable prospect lists, and analytics. Its Home tab shows dashboards, appointments, and tasks according to role and permissions. Applications originate from recruited prospects, and the consoles help admissions staff work from the applicant information captured on person records and related admissions records. Education Analytics dashboards provide additional insights into application status, review status, admission efficiency, and decision outcomes."],connections:[{"planet":"agentforce","desc":"Admissions agent answers applicant questions"}]}
  ],
  dataFlow: ["Start applications for recruited prospects, who are already represented by Person Accounts, and retain applicant information on the person record.","Start a preliminary application in the Education Portal and select an eligible Learning Program, Academic Term, and application timeline.","Complete application stages, upload required documents, submit the application, and coordinate application fees and financial aid packaging.","Verify submitted materials, assign Application Review records, and collect rubric scores and reviewer recommendations.","Record and release the Application Decision, expose status in the applicant portal, and use an AI agent to answer applicant questions.","Enroll the admitted learner in the selected Learning Program, Learning Program Plan, and Academic Term."],
  connections: [{"planet":"recruitment","desc":"Applications originate from recruited prospects"},{"planet":"records","desc":"Applicant data stored on person records"},{"planet":"enrollment","desc":"Admitted students enroll in programs"},{"planet":"financials","desc":"Application fees and financial aid packaging"},{"planet":"agentforce","desc":"AI agent answers applicant questions"},{"planet":"experience","desc":"Applicant portal for status tracking"}]
},

academics: {
  packages: ["educationcloud"],
  name: "Academic Operations",
  icon: "\u{1F3EB}",
  color: "#8b5cf6",
  description: "Academic Operations is the central Education Cloud domain for creating and maintaining academic offerings and the relationships among them. It models learning programs, courses, academic calendars, Course Offerings and schedules, program plans, requirements, and learning outcomes that define what learners can enroll in. These academic structures support course catalogs, registration, degree planning, learner progress, and tuition and fee processing. Transfer credit processes connect external learning and transcripts to the learner's education history and applicable program requirements.",
  components: [
    {id:"program-management",name:"Learning Program Management",icon:"\u{1F393}",desc:"Learning Program Management models the curricula and requirements that learners complete to obtain a credential in Education Cloud. Staff can create learning programs with Learning Wizard, define enrollment requirements and outcomes, and organize required and elective courses with Learning Program Plan Builder. Published program plans support learner pathways, degree planning, and progress views. Learning programs also define offerings for enrollment and provide structure for applying tuition and fees.",tags:["LearningProgram"],docs:["A Learning Program represents the curricula that a learner must complete to obtain a credential. Learning programs can model degree or credential programs, academic support programs, recreational programs, continuing education, and other offerings. Learning Wizard guides staff through creating a program, marking it active, defining prerequisites, corequisites, recommendations, and other criteria, and adding key or additional learning outcomes.","After creating a learning program, staff use Learning Program Plan Builder to organize its required courses, elective courses, reusable collections, and categories. A Learning Program Plan represents the general set of requirements in effect for a program, while Learning Program Plan Requirement records represent specific requirements such as courses, thesis work, or internships. Plans can be saved as drafts and published when ready; published plans can flow to Intelligent Degree Planning and inform Learner Progress.","Learning programs form part of the foundation for Recruitment & Admissions and Student Success. They define what learners can apply to and enroll in, and their plans provide the requirements used to evaluate progress toward completion. In Student Financials, institutions can apply fees to learning programs and associate price books with academic intervals."],docUrl:"https://developer.salesforce.com/docs/platform/data-models/guide/academic-operations.html",connections:[{"planet":"enrollment","desc":"Students enroll in programs"},{"planet":"success","desc":"Program requirements drive learning plans"}]},
    {id:"course-management",name:"Course Management",icon:"\u{1F4DA}",desc:"Course Management models the learning courses that serve as the basic units of larger academic offerings in Education Cloud. Staff use Learning Wizard to create courses, define enrollment requirements, and associate key and additional learning outcomes. Learning Foundation Item records represent prerequisites, corequisites, and recommended learning, while policy rules can handle complex requirements. Learning courses define what students can enroll in and can be used when applying course-related fees.",tags:["LearningCourse"],docs:["A Learning Course stores detailed information about a specific course within a larger learning framework. Staff create courses from the Academic Operations app with Learning Wizard, where they can make the course active and enter its details. Institutions can also import an existing course catalog by using Course Catalog Business APIs.","Learning Wizard supports prerequisites, corequisites, recommendations, and other enrollment criteria. Requirements can use conditions grouped by logic and represented by Learning Foundation Item records, or policy rules implemented as expression sets in Business Rules Engine. A Learning Rule record connects a Learning record to a rule-based requirement.","Every learning has a default learning outcome related to a Learning Achievement, and staff can add more outcomes when creating or editing a course. Courses can be added to required or elective sections of a Learning Program Plan and then scheduled as Course Offerings. Course structures support course catalog, registration, degree planning, learner progress, and the application of course fees."],connections:[]},
    {id:"course-offerings",name:"Course Offerings",icon:"\u{1F4C5}",desc:"Course Offerings make Learning Courses concrete in time and space in Education Cloud. Each offering provides details such as its Academic Session, faculty, location, and start and end dates. Course Offering Schedule records capture meeting details and variations within an offering. Course Offerings support course search, registration, enrollment participation, and academic performance processes.",tags:["CourseOffering"],docs:["A Course Offering is an instance of a training course with location and date details. Institutions create an offering for each instance of a Learning Course that learners can choose. Its specific details include the Academic Session, faculty, location, and start and end dates, making offering timing dependent on the session in the institution's academic calendar.","Course Offering Schedule records tell students when and where to attend and support variations in a section's schedule. For example, separate schedule records can represent meetings held in different locations or at different times on different days of the week. Course Offering Schedule Template records can also be included in the academic operations data model.","Course Search presents course and section details to students, while Course Registration lets permitted students add sections to a cart and enroll. Registration checks availability, eligibility, and scheduling conflicts before creating a Course Offering Participant record that links the student, Course Offering, and Academic Term Enrollment. Course Offering Participant Result records support outcomes such as grades and can trigger Education Cloud flows for alerts or academic support."],connections:[{"planet":"enrollment","desc":"Students register for course offerings"},{"planet":"appointments","desc":"Academic advising precedes course registration"}]},
    {id:"academic-terms",name:"Academic Terms",icon:"\u{1F4C6}",desc:"Academic Terms are part of the hierarchical academic calendar used by Education Cloud to organize academic activity. An Academic Year contains Academic Terms, and Academic Sessions specify the periods when courses are offered. Terms can support reporting, application timelines, registration, course offerings, and fee management. The calendar is flexible enough to represent overlapping terms, different school schedules, and nontraditional intake cycles.",tags:["AcademicTerm","AcademicSession"],docs:["Education Cloud models the academic calendar with Academic Year, Academic Term, and Academic Session records. Academic Year defines the entirety of an institution's academic year. Academic Term specifies an academic period and can contain other time periods, while Academic Session specifies course-offering periods based on semesters, quarters, trimesters, or another institutional calendar.","Institutions can create different Academic Term records for schools that follow different schedules, use short terms for nontraditional intake cycles, or create overlapping terms for special programs. Academic Sessions divide terms into the periods in which courses are offered, including shorter sessions within a longer term. Staff create and activate term and session records from their respective objects.","Academic calendar records support admissions, course scheduling, registration, and student financial processes. Active Academic Terms can appear in application and course-registration experiences when related configuration requirements are met. Student Financials associates price books with an Academic Session, Academic Term, or Academic Year so that fees can be managed for the appropriate academic interval."],connections:[{"planet":"financials","desc":"Terms drive tuition fee schedules"}]},
    {id:"learning-objectives",name:"Learning Objectives",icon:"\u{1F3AF}",desc:"Learning Objectives are modeled through Learning Outcome Item, Learning Achievement, and Learning Foundation Item records in Education Cloud. A Learning Outcome Item maps a learning to its related outcome, while a Learning Achievement represents the outcome of a learning activity. Staff can define key and additional outcomes while creating courses and programs in Learning Wizard. These outcomes provide academic structure that Student Success can use for competency and learner progress tracking.",tags:["LearningOutcomeItem"],docs:["Learning Achievement represents the outcome of a learning activity, and Learning Outcome Item represents the mapping between a learning and its related outcome. Every learning has a default learning outcome related to a Learning Achievement. When creating a Learning Course or Learning Program, staff can add key learning outcomes and additional learning outcomes and designate a primary key outcome.","Learning Foundation Item represents a prerequisite, corequisite, or recommended learning required for a learning outcome. Academic Operations enables staff to manage Learning Outcome Item and Learning Foundation Item records and associate them with Learning Achievements. When course or program requirements are edited in Learning Wizard, Education Cloud can dissociate the existing Learning Foundation Item and associate a new one.","Learning outcomes and achievements contribute to the records used by learning programs, program plans, learner pathways, and learner progress. Learning Program Plan Requirement records describe requirements for outcomes included in a program plan. In Student Success, these structures support progress views and competency-oriented academic planning."],connections:[{"planet":"success","desc":"Objectives map to competency assessments"}]},
    {id:"transfer-credits",name:"Transfer Credits & Equivalencies",icon:"\u{1F504}",desc:"Transfer Credits & Equivalencies supports the definition, submission, evaluation, and approval of prior learning in Education Cloud. Applicants submit Course Credit Transfer Application records with prior-learning details and supporting documents, while registrars review transcripts and articulate eligible credits. Learning Equivalency records define the details of equivalencies between external and internal learnings, and achievement mappings specify source and target achievements. Approved credits can be applied to learner program requirements and connected to the learner's education history.",tags:["CourseCreditTransferAppln","LearningEquivalency"],docs:["A transfer credit request uses a Course Credit Transfer Application to request academic credit for courses taken at another institution and applied to a current degree. An application can include potential transfer courses, approved Learning Equivalencies, and verified External Learning Participant Results from a transcript. The request also opens a Case for the registrar, initiating the administrative process for review.","Registrars use External Learning to represent a course, exam, work experience, military experience, or other learning made available by an external provider. Learning Equivalency stores the details of the equivalency between external and internal learnings. Learning Equivalency Achievement Mapping connects a Learning Equivalency with source and target Learning Achievements, and equivalencies can be limited by dates, learning programs, grades, duration, and other configured details.","Applicants can request transfer credit estimates in an admissions application and upload supporting documents such as transcripts or score reports. Registrars review the documentation, select or define equivalencies, and approve eligible Course Credit Transfer Applications; approval is available only when the review type is Official. When the applicant enrolls, approved transfer credits apply toward program requirements, connecting external study with the learner's academic record and progress."],connections:[{"planet":"records","desc":"Transfer credits link to student education history"}]}
  ],
  dataFlow: ["Create Academic Years, Academic Terms, and Academic Sessions to define the institutional calendar.","Create Learning Courses and Learning Programs, then define their requirements, Learning Achievements, and Learning Outcome Items.","Build and publish Learning Program Plans with required courses, electives, reusable collections, and specific program requirements.","Create Course Offerings in the appropriate Academic Sessions and add schedules so learners can search, register, and enroll.","Use program and course structures for tuition and fee processing, and use learning outcomes and plans for competency and progress tracking in Student Success.","Evaluate Course Credit Transfer Applications and Learning Equivalencies, then apply approved transfer credits to learner program requirements and education history."],
  connections: [{"planet":"enrollment","desc":"Programs and courses define what students enroll in"},{"planet":"records","desc":"Transfer credits link to student education history"},{"planet":"financials","desc":"Course structure drives tuition calculation"},{"planet":"success","desc":"Learning objectives tie to competency tracking"}]
},

enrollment: {
  packages: ["educationcloud"],
  name: "Enrollment",
  icon: "\u{1F4D6}",
  color: "#0ea5e9",
  description: "Enrollment in Education Cloud follows admission decisions and records learner participation in academic terms, learning programs, plans, and course offerings. Enrollment records reference courses, programs, and terms from Academic Operations and connect learners through person accounts or Learner Contact relationships. Course Registration evaluates availability, eligibility, holds, waitlists, prerequisites, corequisites, and schedule conflicts, triggers fee calculation, and can require advising appointments. Results, learning achievements, GPA calculations, Learner Pathways, and Learner Progress provide academic progress information for degree planning and student success tracking.",
  components: [
    {id:"program-enrollment",name:"Program Enrollment",icon:"\u{1F3C1}",desc:"Program Enrollment records an admitted learner’s participation in a learning program, plan, and academic term. The Enroll Admitted Student action lets staff select the academic term, learning program, and learning program plan for enrollment. Learner Program records use Learner Contact to identify the learner and can include requirements associated with the assigned learning program plan. These enrollment records support degree planning and learner progress views.",tags:["LearnerProgram"],docs:["Learner Enrollment follows the admissions process and uses the Enroll Admitted Student action on an Individual Application record. Staff select a learning program, learning program plan, and academic term, and Education Cloud creates the corresponding enrollment records. The EDU Cloud: Select Enrollment Data and EDU Cloud: Enroll Applicant flows support this process, while the enrollLearner invocable action enrolls the admitted student in a learning program plan. The EDU Cloud: Enroll Applicant Bulk flow supports enrollment of multiple applicants.","A Learner Program associates a learner with an assigned Learning Program Plan. When creating the record for degree planning, populate at least Name, Learning Program Plan, and Learner Contact. Learner Program Requirements identify the requirements that the learner must complete, while Learner Program Requirement Progress stores progress against those requirements. Requirements appear in Intelligent Degree Planner only when the learner has a Learner Program with associated Learner Program Requirements.","Learner Program records contribute to Learner Progress and Learner Progress Summary. These components show enrolled learning programs and the planned, enrolled, completed, and unplanned requirements for each program. Sharing sets can restrict Experience Cloud users to their own Learner Program records by matching the user’s contact to the record’s learner contact."],connections:[{"planet":"admissions","desc":"Enrollment follows admission decisions"},{"planet":"records","desc":"Enrollment links to student person records"}]},
    {id:"course-registration",name:"Course Registration",icon:"\u{1F4DD}",desc:"Course Registration provides a self-service process for finding course sections, adding them to a cart, and submitting eligible selections. Education Cloud checks section availability, scheduling conflicts, prerequisites, corequisites, educational characteristics, and active holds during registration. Course waitlists support fully enrolled sections and can generate enrollment offers when seats become available. Registration also triggers fee calculation and can be paired with advising appointments.",tags:["CourseOfferingParticipant"],docs:["Course Search and Registration lets students search for courses, review section details, and add sections to a cart. The cart shows section information, meeting times, instructor details, current enrollment, and the learner’s selected sections. During registration, Education Cloud verifies availability, scheduling conflicts, and learner eligibility before accepting final selections. After registration, Education Cloud creates a Course Offering Participant record and keeps the enrollment record updated when the student changes enrollment details.","Advanced Academic Operations provides course registration, holds management, enrollment policy enforcement, and access to Business Rules Engine (BRE). Active holds automatically block registration when their restrictions apply to Course Registration. Educational characteristics can represent time-bound attributes such as field of study, cohort affiliation, or academic level, and registration evaluates those attributes against course requirements. Time conflict warnings are automatic, and the optional Enforce Time Conflicts setting blocks registration for overlapping sections.","Course waitlists let eligible students join fully enrolled sections and monitor their position. Registrars configure a course offering’s Waitlist Status and waitlist capacity, then use prebuilt flows to generate and send enrollment offers and expire unaccepted offers. The Participation Status field on Course Offering Participant must use the documented values and API mappings for course registration, waitlists, degree planning, and GPA calculation to work as designed. Relevant values include In Cart, On Hold, Enrolled, Waitlisted, Dropped, Completed, Failed, Transfer Credit, and Withdrew.","Course registration triggers fee calculation for the selected academic offerings. Education Cloud Student Financials applies fees to learning programs and courses through its fee management framework. Registration can also require advising appointments, which learners or staff can schedule through Education Cloud Appointment Management."],connections:[{"planet":"academics","desc":"Registration references course offerings"},{"planet":"financials","desc":"Registration triggers fee calculation"}]},
    {id:"academic-achievement",name:"Academic Achievement",icon:"\u{1F3C6}",desc:"Academic Achievement models the outcomes of learning activities and connects those outcomes to courses, programs, and other learning records. Course Offering Participant Result records capture learner outcomes for specific course participation and can initiate academic support automation. Policy rules and expression sets calculate academic scores such as term GPA. Learner Progress and Learner Progress Summary present achievement and requirement data to learners and advisors.",tags:["LearningAchievement"],docs:["A Learning Achievement represents the outcome of a learning activity. Education Cloud requires Learning Achievement record types and Learning Achievement Configuration records for supported achievement types, including Learning Course, Learning Program, and Achievement Group. Learning Outcome Items map a learning to its related outcome, and Learning Foundation Items represent prerequisites, corequisites, or recommended learning. Academic Operations staff can create learning outcomes and associate them with learning achievements through Learning Wizard.","Course Offering Participant Result records store results associated with participation in a course offering. The EDU Cloud: Create Grade Alert flow launches when a Course Offering Participant Result is updated and can create an alert when a learner’s grade drops below a C. Academic Score Calculations use the student information system policy rules framework, a context definition, and a policy rule to calculate GPA for students enrolled in an academic term. After calculation, staff can review an Academic Score Report and publish the scores for display in Learner Progress Summary.","Learner Progress shows planned, enrolled, completed, and unplanned requirements for each enrolled learning program. It includes grades, results, completed duration, repeated courses, and messages for unplanned or failed requirements that require attention. Learner Progress Summary adds completion percentage, credits, enrollment, and term details, giving learners and advisors academic progress data for degree planning and student success tracking."],connections:[{"planet":"success","desc":"Achievements feed student success tracking"}]},
    {id:"enrollment-status",name:"Enrollment Status Management",icon:"\u{1F4CA}",desc:"Enrollment Status Management uses status fields on academic term, program, and course participation records to represent a learner’s current enrollment state. The Participation Status field on Course Offering Participant is a dynamic picklist whose documented values support registration, degree planning, and GPA calculation. Waitlist and hold processes update or restrict participation as learners move through registration. Academic term enrollment records also provide the active term context used by registration, GPA calculation, and learner progress.",tags:["LearnerProgram"],docs:["The Participation Status field on the Course Offering Participant object represents the state of course participation. Education Cloud documents picklist values and API mappings for Audit, Completed, Declined Waitlist, Dropped, Enrolled, Facilitating, Failed, In Cart, On Hold, Transfer Credit, Waitlisted, and Withdrew. Enrollee Count and Waitlist Count don’t recognize custom picklist values for Participation Status and Waitlist fields. Institutions should therefore use the documented values when configuring course registration, degree planning, and GPA calculation.","Waitlist status is managed at both the course offering and participant levels. A course offering can have a Waitlist Status of Open and a configured waitlist capacity, while a learner’s Course Offering Participant record uses Participation Status to represent waitlisted or enrollment-related states. Registrars can manually change a participant to Waitlisted, Removed from Waitlist, or Eligible to Enroll from Waitlist as part of waitlist management. Prebuilt waitlist flows can generate offers, notify students, and expire offers according to configured timing.","Academic Term Enrollment records identify a learner’s enrollment in a term and must include the learner, enrollment date, enrollment reason, and enrollment status for Course Registration setup. Holds and Blocks can prevent a learner from registering until the associated restriction is resolved. When a learner enrolls in an academic term, the EDU Cloud: Close Related Cases for Term flow can automatically close a related open application case. These status-driven processes keep enrollment administration aligned with institutional policies."],connections:[{"planet":"financials","desc":"Financial holds affect enrollment status"}]},
    {id:"learning-plans",name:"Learning Plans",icon:"\u{1F5FA}",desc:"Learning Plans use Learner Pathway records to model a learner’s planned path toward completion of enrolled learning programs. Intelligent Degree Planner provides a drag-and-drop canvas for arranging courses by academic year, term, and session. Learner Pathway Templates can give learners a predefined starting point, while Learner Program Requirements supply the courses and placeholders available for planning. Saved pathway data feeds Learner Progress and can be submitted for advisor approval when an approval process is configured.",tags:["LearnerPathway"],docs:["Intelligent Degree Planner lets learners and advisors visualize paths to degree completion in the same planning interface. Users arrange academic years, terms, sessions, courses, and requirement placeholders on a drag-and-drop canvas. The planner tracks planned, unplanned, and required units in real time. All plan data is saved in a Learner Pathway, and courses placed within the pathway are saved as Learner Pathway Items.","Learner Pathway Templates provide reusable starting points for degree planning. Templates can include Learning Pathway Template Items and Learning Pathway Template Program Plans, and they become available to learners when their status is Active. The Learner Pathway Builder verifies prerequisite and corequisite ordering when users save, and the Verify Program Requirements button performs the same check when Automatically Validate Pathway Selections is off. Validation warnings identify affected courses but don’t prevent the pathway from being saved.","Intelligent Degree Planning depends on learning, program, course, outcome, achievement, foundation, program plan, learner program, academic year, term, session, and course offering data. A learner must have a Learner Program with associated Learner Program Requirements for requirements to appear in the planning panel. The global action for creating a Learner Pathway is configured with Name, Learner Contact, and Description, and Learner Contact defaults to $User.ContactId. Sharing sets can then limit learners to pathways associated with their own contact."],connections:[{"planet":"success","desc":"Learning plans support student success tracking"},{"planet":"appointments","desc":"Plan adjustments often require advising appointments"}]}
  ],
  dataFlow: ["Receive the admission decision and enroll the admitted learner in the selected academic term, learning program, and learning program plan.","Link Learner Program, academic term enrollment, and course participation records to the learner’s person account or Learner Contact while referencing configured courses, programs, and terms.","Evaluate course availability, eligibility, prerequisites, corequisites, holds, waitlists, and schedule conflicts, and schedule an advising appointment when required.","Register eligible course selections and trigger fee calculation for the applicable learning programs and courses.","Record participation results, learning achievements, credits, and GPA calculations, then feed Learner Pathways and Learner Progress into degree planning and student success tracking."],
  connections: [{"planet":"admissions","desc":"Enrollment follows admission decisions"},{"planet":"academics","desc":"Enrollment references courses, programs, and terms"},{"planet":"records","desc":"Enrollment records link to person accounts"},{"planet":"success","desc":"Enrollment progress feeds student success tracking"},{"planet":"financials","desc":"Course registration triggers fee calculation"},{"planet":"appointments","desc":"Registration may require advising appointments"}]
},

records: {
  packages: ["educationcloud"],
  name: "Student Records",
  icon: "\u{1F464}",
  color: "#10b981",
  description: "Student Records is the person-centered domain that anchors the learner lifecycle in Education Cloud through Person Accounts and related person data. Recruitment creates prospect records, and admissions enriches them with applicant details, education history, examinations, languages, demographics, contact points, and relationships; academics uses education history for transfer credit evaluation, while enrollment uses the same student identity for enrollment records. Student success links competencies and traits, Student Financials links financial accounts, Mentoring references mentor and mentee profiles, Alumni Relations tracks alumni engagement, and Appointment Management references the learner's record. Data 360 connects institutional sources and applies identity resolution so duplicate identities can contribute to a unified learner profile.",
  components: [
    {id:"person-accounts",name:"Person Accounts",icon:"\u{1F464}",desc:"Person Accounts represent individual students, staff, applicants, alumni, and other constituents in Education Cloud. They combine account and contact information in a single Account record and provide the identity foundation for a unified student record. Recruitment and admissions create and populate person records, while enrollment, student success, financials, mentoring, alumni engagement, and appointments use the same learner identity.",tags:["Account","Contact"],docs:["In Education Cloud, data about individual people is stored on the Account object as Person Accounts. Person Accounts combine account and contact information into a single record and model faculty, staff, administrators, students, and alumni. Constituent Role records can track the current and past roles that a person has with the institution over time.","Student Management centralizes personal details, emergency contacts, relationships, contact information, and enrollment data in a single student view. Student and alumni Account record pages can combine profile information with related academic, advising, appointment, relationship, education, and employment records. Access to these records can be assigned to staff such as advisors, registrars, and faculty.","Recruitment uses lead records for suspects and converts interested prospects to Person Accounts. When an applicant registers on the learner portal, Education Cloud automatically creates a Person Account, and submitted applicant information is associated with that person. Data 360 connects and harmonizes data from institutional systems into a unified learner profile, and identity resolution rules link multiple data sources into a unified profile."],connections:[{"planet":"enrollment","desc":"Person accounts are the identity anchor for enrollments"},{"planet":"admissions","desc":"Applicants are linked to person accounts"}]},
    {id:"contact-points",name:"Contact Points",icon:"\u{1F4DE}",desc:"Contact Points store the addresses, phone numbers, and email addresses associated with a person in Education Cloud. Student Management can expose Contact Point Addresses, Contact Point Phones, and Contact Point Emails on the Person Account page layout. These records support a consolidated view of student contact information and can distinguish the purpose or primacy of a contact method.",tags:["ContactPointAddress","ContactPointPhone","ContactPointEmail"],docs:["The Student Management Account Record Page can include related lists for Contact Point Addresses, Contact Point Phones, and Contact Point Emails. Adding these related lists to the Person Account page layout gives staff access to a learner's additional contact information from the student record. This information appears alongside personal details, emergency contacts, citizenship information, demographics, and enrollment data.","Contact Point Address supports management of multiple addresses for a constituent. Usage Type can indicate whether an address is Home, Work, Temporary, or Inactive, and an address can be designated as primary. Education Cloud also supports Automatic Person Account Mailing Address Synchronization so that changes to a Person Account mailing address can create or update the corresponding Contact Point Address.","Data 360 financial aid setup maps ContactPointEmailDmo, ContactPointPhoneDmo, and ContactPointAddressDmo after the Individual DMO. ContactPointEmailDmo stores the student's email address and can identify the primary email, while ContactPointPhoneDmo stores the student's phone number. ContactPointAddressDmo stores the mailing address used for residency determination and tuition calculation."],connections:[]},
    {id:"relationships",name:"Relationships & Household",icon:"\u{1F46A}",desc:"Relationships & Household models how learners connect to family members, households, organizations, services, and other individuals. Education Cloud uses household accounts, Group Membership objects, Account Contact Relationships, and Contact Contact Relationships for these connections. Actionable Relationship Center can display the resulting household and relationship information as a graph on student or alumni records.",tags:["ContactContactRelation"],docs:["Person Accounts represent nearly all individuals, while household accounts represent families and business accounts represent organizations, schools, colleges, departments, and services. Group Membership objects link individuals to households, other individuals, services, or organizations. Education Cloud requires contacts to be related to multiple accounts and Group Membership to be enabled for household modeling.","Contact Contact Relationship is the documented object name, and its API name is ContactContactRelation. Application records can use Contact Contact Relationship to represent relationships between an applicant and a guardian, sibling, recommender, or other related person. Party Role Relationship records define paired roles such as Guardian and Child, Sibling and Sibling, or Recommender and Applicant.","Student Management can add a relationship graph created from the Education Cloud Person Account Relations template. The graph shows household members such as parents, guardians, and siblings and the relationships among them. Emergency contacts can also be displayed through a dynamic related list based on Contact Contact Relationship."],connections:[{"planet":"mentoring","desc":"Mentoring profiles reference person relationships"}]},
    {id:"education-history",name:"Education History",icon:"\u{1F4DC}",desc:"Education History captures a person's prior education and supports admissions, alumni engagement, and transfer credit processes in Education Cloud. Person Education records store education history associated with a Person Account, while Person Academic Credential records represent credentials such as degrees, certificates, or badges. Registrars can use prior education and external learning information when evaluating transfer credit requests.",tags:["PersonEducation"],docs:["Admissions applications collect secondary school, college, or university education information from applicants. Education Cloud can prefill previously stored education information in later applications, while individual application task item records let applicants control which information is included for review. Admissions staff can verify education records and set their verification status during application processing.","The alumni Account record page can display Person Education and Person Academic Credential related lists. Person Academic Credential records can be created when a learner program is marked complete, while Person Education records provide education history from institutions or grade levels. Alumni users can also be granted access to maintain Person Education records through an Experience Cloud site.","Transfer credit evaluation uses prior learning, transcripts, external learning, learning equivalencies, and course credit transfer applications. A registrar reviews submitted documentation and maps eligible prior learning to institutional courses or program requirements. Person Education is also included in the Student Success bundle of the Education data kit for use in Data 360."],connections:[{"planet":"academics","desc":"Education history informs transfer credit evaluation"}]},
    {id:"examinations",name:"Examinations & Test Scores",icon:"\u{1F4DD}",desc:"Examinations & Test Scores records standardized examinations and the scores supplied by applicants or students. Person Examination represents submitted test results and can support a hierarchy of composite and section-level scores. Student Management displays standardized test results, while admissions staff can verify or add examination records during application review.",tags:["PersonExamination"],docs:["Institutions create Examination records for standardized tests such as SAT, ACT, and Other. Applicants then provide test names, dates, and scores through the Test Results stage of an application. A Person Examination record represents the composite score or a single-section score associated with the applicant.","Some standardized tests use a two-level Person Examination hierarchy. For example, an ACT result can have a parent record for the composite score and child records for Science, Math, or other section scores. Education Cloud recommends a flow that deletes child Person Examination records when the parent record is deleted.","The Student Management app includes a Standardized Tests tab that lists the results of tests taken by a student. Admissions staff can also add test results from an Individual Application record and add subject-specific scores to the test record. Application permission sets can grant applicants, processors, and reviewers the required access to Person Examination records."],connections:[{"planet":"admissions","desc":"Test scores inform admission decisions"}]},
    {id:"demographics-languages",name:"Demographics & Languages",icon:"\u{1F30D}",desc:"Demographics & Languages brings biographic and demographic details together with a person's language information in Education Cloud. Contact Profile stores details such as birth date, ethnicity, first-generation status, citizenship, and other profile data associated with the Contact record. Person Language records capture a person's language and proficiency information for applications and the broader learner profile.",tags:["PersonLanguage","PersonEmployment"],docs:["The Contact Profile object is associated with Contact and tracks biographic and demographic information. Education Cloud can combine data from Person Accounts and related Contact Profile records into a unified student record. Student Management presents citizenship and demographic information in the Learner Profile view alongside personal and contact details.","Applicants can provide language proficiency information in an admissions application, creating Person Language records. The admissions data model uses these records to represent a person's proficiency in a given language. Person Language is also included in the Student Success bundle of the Education data kit for Data 360.","Career planning and student support can use additional person-centered records such as Person Trait, Person Competency, and Person Affinity. These records capture characteristics, proficiencies, preferences, and interests that advisors can use when supporting students. They remain linked to the same person identity represented by the Person Account and Contact."],connections:[{"planet":"alumni","desc":"Employment data tracks post-graduation outcomes"}]}
  ],
  dataFlow: ["Create Person Accounts from prospect data and enrich them with applicant information during recruitment and admissions.","Add contact points, household relationships, demographics, languages, education history, examinations, and employment to the person record.","Use education history for transfer credit evaluation and reference the same student identity from enrollment and academic records.","Link student success competencies and traits, financial accounts, mentoring profiles, and appointment records to the person.","Track alumni status and engagement on the continuing person record after the learner completes their studies.","Resolve duplicate identities with Data 360 and harmonize institutional data into a unified learner profile."],
  connections: [{"planet":"recruitment","desc":"Prospect data creates person records"},{"planet":"admissions","desc":"Applicant data stored on person records"},{"planet":"academics","desc":"Education history informs transfer credit evaluation"},{"planet":"enrollment","desc":"Student identity for all enrollment records"},{"planet":"success","desc":"Competencies and traits linked to person"},{"planet":"financials","desc":"Financial accounts linked to person records"},{"planet":"mentoring","desc":"Mentor/mentee profiles reference person records"},{"planet":"alumni","desc":"Alumni status tracked on person records"},{"planet":"appointments","desc":"Appointments reference student records"},{"planet":"data360","desc":"Identity resolution unifies duplicate person records"}]
},

success: {
  packages: ["educationcloud"],
  name: "Student Success",
  icon: "\u{1F31F}",
  color: "#22c55e",
  description: "Student Success in Education Cloud provides tools to support learners across academics, financial aid, careers, wellbeing, and life goals through cases, success teams, care plans, alerts, appointments, programs, and learner progress. Unified person records bring relevant academic performance, competencies, traits, affinities, mentoring outcomes, and success metrics into context for proactive interventions and personalized engagement. Advisors and learners collaborate through the Student Success app, configurable consoles, and self-service portal components, while Education Analytics supplies dashboards and institutional KPIs. Student Advising Topics can summarize advising cases, answer campus resource and policy questions, and suggest next-best actions, while the separate Course Operations Agent can identify at-risk students.",
  components: [
    {id:"competency-tracking",name:"Competency Tracking",icon:"\u{1F4AA}",desc:"Competency Tracking in Education Cloud records the skills and proficiencies associated with a learner. A Person Competency identifies a Competency, proficiency level, verification status, effective dates, and stage, and the associated person can be an account or a contact. Learning outcomes and learning achievements from Academic Operations provide related academic context, while competency data can ground personalized student goal recommendations.",tags:["PersonCompetency"],docs:["Person Competencies give advisors and learners a structured way to document competencies acquired through coursework, cocurricular and extracurricular activities, internships, community service, and other experiences. When creating a Person Competency, users select the person’s proficiency level, verification status, effective dates, Competency, and stage. The person associated with the competency can be either an account or a contact. Students can also add competencies as interested or acquired through the learner portal.","Competency data supports Career Planning and Life Goals and the Student Goals Agent. The EDU Cloud: Get Learner Details flow collects Person Competencies with traits, affinities, involvement groups, academic profile information, and assessment results to ground recommendations. Administrators configure values for Proficiency Level and Verification Status and provide the required object permissions and record access. Academic Operations separately models learning outcomes and learning achievements that describe the results of learning activities."],connections:[{"planet":"academics","desc":"Learning objectives map to competency assessments"}]},
    {id:"traits-affinities",name:"Traits & Affinities",icon:"\u{1F9E0}",desc:"Traits & Affinities in Education Cloud captures student characteristics, preferences, and interests for personalized guidance. Person Trait records use a contact and include information such as Type, Category, and Source, while Person Affinity records use a contact and include Type, Category, Sub Category, Source, and Active information. These records can ground career and life goal recommendations alongside competencies, assessments, involvement groups, and academic profile data.",tags:["PersonTrait","PersonAffinity"],docs:["Person Traits reflect a student’s current profile, including strengths and opportunities. When creating a Person Trait, users enter a name, select Type and Category, associate a contact, and select the information Source. Administrators define the applicable Type, Category, and Source picklist values because these picklists have no values by default. Advisors can use traits with other student profile information to personalize guidance.","Person Affinities represent a student’s past and current interests. Users enter a name and description, associate a contact, select Type, Category, Sub Category, and Source, and indicate whether the affinity is active. The EDU Cloud: Get Learner Details flow can collect Person Traits and Person Affinities to ground Student Goals Agent recommendations. Portal and advisor permission sets must provide appropriate access to these records."],connections:[]},
    {id:"advising",name:"Academic Advising",icon:"\u{1F91D}",desc:"Academic Advising in Education Cloud uses cases as advising workspaces where advisors coordinate success teams, care plans, tasks, alerts, and appointments. Course performance and learner progress can inform interventions, while advisors and learners collaborate through the Student Success app and learner portal. Student Advising Topics in Agentforce can summarize advising cases, answer questions about campus resources and policies, and suggest next-best actions. Education Analytics provides advisor and director dashboards and student success KPIs.",tags:["CaseTeamMember","CaseTeamRole"],docs:["Institutions configure advising by enabling Student Success, creating a support process, and defining advising Case record types. Case record types represent distinct advising workspaces such as academic, career, or wellbeing support. Case team roles define staff responsibilities and access, while predefined case teams group staff into reusable teams. Success Team records enable advising workspaces and can connect predefined case teams as support pools.","Advisors can create personalized care plans on learner cases or related alerts. Care plans contain goals, tasks, and benefits, and adding a benefit can automatically enroll the learner in the associated program. Advisors can also add individual case team members or predefined case teams to an advising case. Assigned team members can support learners through scheduled in-person, phone, or virtual appointments.","The advisor console provides access to care plans, alerts, analytics dashboards, advisor insights, and KPIs. Learner portal components let students view their success teams and care plans, manage assigned tasks, and schedule appointments. Student Advising Topics in Agentforce can use advising cases, campus-resource data, and policy knowledge to assist advisors. Advising summaries and suggested next-best actions help advisors prepare for conversations and follow up proactively."],docUrl:"https://developer.salesforce.com/docs/platform/data-models/guide/student-success.html",connections:[{"planet":"appointments","desc":"Advising sessions scheduled as appointments"},{"planet":"agentforce","desc":"AI advising agent surfaces at-risk students"}]},
    {id:"academic-alerts",name:"Academic Alerts",icon:"\u{26A0}",desc:"Academic Alerts in Education Cloud use Record Alerts related to Case records to highlight learner performance or record changes that require action. Advisors can create alerts manually or use flows to automate alerts and task assignments. Documented flows include a grade alert when a learner’s grade falls below a C and academic probation advisor assignment when GPA falls below 2.5. The Course Operations Agent can identify at-risk students and coordinate support, while Student Advising Topics focuses on case summaries, campus questions, and next-best actions.",tags:["Case"],docs:["Record Alerts help advisors monitor grades, attendance, behavior, courses, and other conditions that can impede learner success. Institutions can configure alert categories and severity levels, create alerts manually in the Student Success app, or use flows to automate and mass-apply alerts. The EDU Cloud: Create Grade Alert flow launches when a Course Offering Participant Result is updated and creates an alert when a grade falls below a C. If the learner has a failing grade, the flow also creates a task for a case team member.","Advisors can view alerts associated with a learner, change the status of multiple alerts, and apply a care plan to an alert or a selected group of alerts. Course-result and GPA-based flows can also assign specialized support teams, including an academic probation advisor when GPA falls below 2.5. Course performance therefore feeds targeted student success interventions. Separately, the Course Operations Agent can identify at-risk students, show risk factors, create Record Alerts, and establish Slack channels for intervention coordination."],connections:[{"planet":"enrollment","desc":"Enrollment data triggers academic alerts"}]},
    {id:"career-development",name:"Career Development",icon:"\u{1F680}",desc:"Career Development in Education Cloud combines career and life goals, career and interest assessments, involvement groups, competencies, traits, and affinities. Students can create goals, track tasks, explore campus activities, and maintain a profile of their interests and capabilities through the learner portal. Advisors can review the same information in the Student Success app and recommend appropriate assessments, involvement groups, competencies, and action plans. The Student Goals Agent can suggest SMART goals and recommend courses, support programs, and involvement groups based on student-specific context.",tags:["PersonCompetency","PersonAffinity"],docs:["Career Planning and Life Goals provides tools for students to define and manage goals beyond academics. Goal assignments can include a custom goal name, description, category, status, effective dates, target completion date, and related tasks. Students can track goals and tasks in the portal, while advisors can create personalized goals from a student’s case record. Action plans and campus resources help turn broad objectives into manageable steps.","The career and interest assessment library uses Discovery Framework and Omniscripts to collect student preferences and assessment responses. Advisors create assessment questions and publish assessment forms, and students can start, resume, complete, and review assessments through the portal. Involvement groups represent activities such as student organizations, leadership roles, and community service. Students can explore or self-enroll in eligible groups and track the competencies associated with their participation.","The EDU Cloud: Get Learner Details flow gathers Person Traits, Person Competencies, Person Affinities, involvement groups, first-generation status, academic profile information, and submitted assessments. The Student Goals Agent uses this context to recommend specific, measurable, achievable, relevant, and time-bound goals and relevant campus resources. Mentoring programs can also provide career guidance, professional networking, internship and job-search advice, and skill development. Mentoring assessments and outcomes can contribute to the broader tracking of student development and success."],connections:[{"planet":"alumni","desc":"Alumni career data informs current student planning"}]}
  ],
  dataFlow: ["Unify learner competencies, traits, affinities, goals, and success metrics on person records.","Bring course performance, learning outcomes, and mentoring outcomes into success tracking.","Evaluate grade and GPA conditions, and use the Course Operations Agent to identify at-risk learners.","Create Record Alerts and advising Cases, then assign success teams, care plans, tasks, and benefits.","Schedule advising appointments and use Student Advising Topics to summarize cases and suggest next-best actions.","Review analytics and student success KPIs, then record intervention progress and outcomes."],
  connections: [{"planet":"academics","desc":"Learning objectives tie to competency tracking"},{"planet":"enrollment","desc":"Course performance feeds success interventions"},{"planet":"records","desc":"Success metrics stored on person records"},{"planet":"mentoring","desc":"Mentoring outcomes feed into success tracking"},{"planet":"appointments","desc":"Advising appointments support interventions"},{"planet":"agentforce","desc":"AI advising agent surfaces at-risk students"}]
},

financials: {
  packages: ["educationcloud"],
  name: "Student Financials",
  icon: "\u{1F4B0}",
  color: "#f59e0b",
  description: "Student Financials in Education Cloud connects learner person records with tuition, fees, academic orders, invoices, balances, payments, and financial aid. Academic program and course structures drive fee schedules, admissions supports application fees and financial aid packaging, and registration can trigger tuition charges. The Education Portal provides student financial self-service, while the Student Financials Agent and Financial Aid Agent answer account, fee, billing, and aid questions and analytics provide staff with financial health insights. Scholarship and grant information can connect student aid with alumni and advancement funding processes.",
  components: [
    {id:"fee-management",name:"Fee Management",icon:"\u{1F4B5}",desc:"Fee Management models tuition, meal plans, lab fees, and other student charges as products in Education Cloud. Institutions group these products into price books and associate the price books with academic sessions, terms, or years. This framework supports fees that change over time or vary according to learner attributes. Student Financial Account Management requires Education Cloud, Revenue Cloud Advanced, and Revenue Cloud Billing.",tags:["Product2"],docs:["Education Cloud uses products to represent student fees such as in-state tuition, international student tuition, lab fees, and meal plans. Staff create a price book, add the applicable products, and enter the pricing information for each product. Multiple price books can represent fees that change by academic year or vary for different groups of learners.","Price books are associated with academic intervals through Price Book Academic Intervals. An academic interval can be an academic session, term, or year, and multiple price books can be associated with the same interval. The institution's academic year, term, and session structure therefore provides the time context for fee management.","Before configuring fees, administrators turn on Set Up Student Financial Account Management and configure orders, pricing, billing, and payments. Education Cloud also requires appropriate sharing access for products, academic intervals, orders, academic orders, and related billing records. Academic program and course structures provide the basis for applying tuition and fees, while registration processes can trigger the creation of learner charges."],connections:[{"planet":"academics","desc":"Course and program structure determines applicable fees"}]},
    {id:"price-books",name:"Price Books & Schedules",icon:"\u{1F4D5}",desc:"Price Books & Schedules organize fee products, their prices, and the academic intervals in which those prices apply. A price book can contain multiple fee products, and an academic interval can use multiple price books. When an order is activated, Education Cloud automatically creates a billing schedule for each order item. Those schedules determine when and how much to invoice.",tags:["Pricebook2","PricebookEntry"],docs:["Staff create price books in the Student Financials app and add products that represent tuition, fees, meal plans, and other charges. Each price book entry provides the pricing relationship between a product and a price book. Institutions can maintain separate price books when prices change over time or differ according to learner attributes.","A Price Book Academic Interval associates a price book with an academic session, term, or year. This association lets Education Cloud apply prices within the institution's academic calendar. The Price Book Academic Interval Entries decision table template is also available as a pricing resource for academic interval price book entries.","After products are added to an order, staff activate the order to begin billing. Education Cloud creates a billing schedule record for each order item, and the schedule defines the invoice timing and amount. Billing policies, treatments, payment terms, and tax policies can then be configured to support the institution's financial model."],connections:[]},
    {id:"academic-orders",name:"Academic Orders",icon:"\u{1F6D2}",desc:"Academic Orders connect learner orders to academic intervals in Education Cloud. The Create Learner Order invocable action creates an order for a learner and an associated academic order for that learner and academic term. Staff can also create the order manually, add products, and then create a separate academic order that selects the applicable interval. Activating the order creates billing schedules that support automated invoice generation.",tags:["Order","OrderProduct","AcademicOrder"],docs:["Education Cloud provides the Create Learner Order invocable action for creating academic orders for one or more learners. The action creates an order for the learner and an associated academic order for the learner and academic term. Institutions can incorporate the action into flows, Business APIs, and Omnistudio Flexcards, and Salesforce recommends using a flow and batch management for bulk calculations.","For manual order creation, staff create an order, specify the account, start date, billing contact, and addresses, and then add products from a selected price book. Each order product includes a quantity and unit price, with an optional line description. The order itself does not hold the academic interval; to link the order to an academic interval, staff create an academic order and select the interval on that separate record.","An order is activated after its products and academic context are established. Activation creates a billing schedule for each order item, and automated invoices are generated from those schedules. An invoice lists the order products and the total amount the student must pay."],connections:[{"planet":"enrollment","desc":"Course registration triggers order generation"}]},
    {id:"payment-processing",name:"Payment Processing",icon:"\u{1F4B3}",desc:"Payment Processing supports invoicing, account reconciliation, and student payments in Education Cloud. The learner portal can present charges, adjustments, balances, invoices, payment status, and payment history in a unified financial experience. Students can initiate payments through a configured Payment Checkout page. Institutions configure a merchant account, payment methods, and a channel for payment data to flow from the payment gateway to Salesforce Payments.",tags:["Order"],docs:["Education Cloud reconciles student accounts through an order-to-invoice process. Billing policies, treatments, payment terms, and tax policies control invoice generation and payment timing, while posting an invoice records the financial obligation on the student's account. Credit memos can provide general adjustments or be applied to invoice lines, and invoice settlement information reflects payments and credits.","The learner portal can include Financial Status at a Glance, Accounts Overview, Academic Year Charges, and posted invoice components. Financial Status at a Glance shows total charges, adjustments, balance due, next due date, and payment status. This self-service experience gives students access to invoices, running balances, and payment histories while reducing administrative inquiries.","To enable payments, administrators configure a merchant account and its payment methods, add the merchant account ID to the Payment Checkout page, and set up a channel for payment data. Students can then initiate payments from the portal and track their financial activity. Portal access also depends on the documented billing, Student Financials, Advanced Academic Operations, and Omnistudio permissions and sharing settings."],connections:[{"planet":"enrollment","desc":"Financial holds can block registration"}]},
    {id:"financial-aid",name:"Financial Aid",icon:"\u{1F381}",desc:"Financial Aid brings external financial aid management data into Education Cloud through Data 360. Financial aid components present applications, awards, costs, required documents, disbursements, holds, and academic standing to students, prospects, and staff. The Financial Aid Agent answers personalized questions about financial aid status, requirements, awards, estimated cost of attendance, disbursement dates, and satisfactory academic progress. Scholarships and grants can also connect learner support with alumni and advancement funding processes.",tags:["Order","OrderProduct"],docs:["Education Cloud maps external financial aid data to Financial Aid Data Model Objects that represent the lifecycle from application through disbursement. The Individual DMO is central to the model, and financial aid DMOs link to the student through an IndividualId foreign key. Learner Financial Aid Application DMO, Benefit DMO, Benefit Assignment DMO, Required Document DMO, Benefit Disbursement Period DMO, Benefit Disbursement DMO, and learner cost DMOs collectively represent applications, awards, documentation, payment periods, disbursements, and costs.","Financial aid Lightning web components can be added to an Experience Cloud portal or the Person Account record page. The Financial Aid Year Filter is required on a page that contains other financial aid components because it loads and distributes data for the selected award year. Optional components include Financial Aid Highlights, Financial Aid Overview, Financial Aid Checklist, Financial Aid Applications, Financial Aid Awards, and Financial Aid Disbursements.","Financial Aid Awards organizes award information into Grants and Loans tabs and calculates offered and accepted aid using Benefit Assignment DMO data. Financial Aid Overview shows cost of attendance, total aid, and cost breakdown, while Financial Aid Disbursements distinguishes paid and scheduled disbursements. Source values must match the documented display logic or be remapped before they are mapped to the DMOs.","The Financial Aid Agent uses Data 360 data to answer questions for authenticated students and password-verified prospects. Before providing personalized information, the agent verifies identity, bypassing email verification for authenticated Experience Cloud users and using a one-time password for unauthenticated prospects. The agent provides factual answers but doesn't accept or decline awards, submit documents or applications, change aid packages, or give financial advice."],connections:[{"planet":"admissions","desc":"Financial aid packaging tied to admission offers"}]}
  ],
  dataFlow: ["Define academic programs, courses, years, terms, and sessions, and use that structure to establish fee products, price books, and fee schedules.","Produce application fees during admissions, and surface financial aid data ingested from an external financial aid management system via Data 360.","Trigger tuition and related charges from registration, then create learner orders and separate academic orders for the applicable academic intervals.","Link each financial account and order to the learner's person record, add priced order products, and activate the order to generate billing schedules and invoices.","Reconcile charges, credits, balances, and payments, and expose invoices, financial status, and payment options through the Education Portal.","Answer account, fee, billing, and financial aid questions with the Student Financials Agent and Financial Aid Agent, and monitor financial health through staff dashboards."],
  connections: [{"planet":"admissions","desc":"Application fees and financial aid packaging"},{"planet":"enrollment","desc":"Registration triggers tuition charges"},{"planet":"academics","desc":"Program and course structure drives fee schedules"},{"planet":"records","desc":"Financial accounts linked to person records"},{"planet":"alumni","desc":"Scholarship funds connect to advancement"},{"planet":"agentforce","desc":"Financial aid agent answers billing questions"},{"planet":"experience","desc":"Student financial self-service portal"},{"planet":"analytics","desc":"Financial health dashboards"}]
},

mentoring: {
  packages: ["educationcloud"],
  name: "Mentoring",
  icon: "\u{1F91D}",
  color: "#f472b6",
  description: "Mentoring in Education Cloud supports structured programs that connect mentees with mentors for academic, professional, and personal development. Facilitators define programs and mentoring benefits, collect assessment responses, and maintain mentoring profiles linked to person records through Contacts and related program enrollment or provider offering records. They compare potential mentors and set Provider on the Benefit Assignment to the selected mentor’s contact value, then manage the relationship with appointments, Timeline, Interaction Summaries, Record Alerts, Action Plans, and related records. Outcome Management evaluates mentoring impact so outcomes can be tracked as student success metrics.",
  components: [
    {id:"program-design",name:"Program Design",icon:"\u{1F4CB}",desc:"Program Design in Education Cloud supports mentoring programs that address participants’ academic, professional, and personal development needs. Facilitators model each mentoring initiative as a support program and define its related mentoring benefits. They can also add intake assessments whose responses help clarify participant needs, preferences, and goals. Programs and benefits can be made available through an Experience Cloud site for mentor and mentee enrollment.",tags:["Program"],docs:["The Mentoring app gives facilitators a central place to create and manage mentoring programs and their benefits. Mentoring is one of the support program types that institutions can use to deliver non-scholastic services and initiatives. A program can support areas such as networking, skill development, academic guidance, and career development. Facilitators can launch workflows from the app to create programs, program enrollments, and benefits.","Program and Benefit Management provides the underlying program structure. Administrators create a Mentoring benefit type and associate mentoring benefits with the appropriate program. A benefit can include a description, availability dates, enrollment information, a unit of measure, and a benefit manager. Selecting Register as Provider lets prospective mentors register to provide the benefit through an Experience Cloud site.","Discovery Framework supports intake assessments for mentoring programs. An assessment with predefined questions can appear when a participant enrolls, and automation saves the submitted responses in records related to the program enrollment. Facilitators review the responses to understand what a mentee needs and what a mentor can provide. Separate assessments can be created for mentors and mentees."],connections:[]},
    {id:"mentor-profiles",name:"Mentor & Mentee Profiles",icon:"\u{1F464}",desc:"Mentor & Mentee Profiles in Education Cloud provide participant information used to connect a mentee with a suitable mentor. Each mentoring profile selects a Contact and uses Related Record to reference either the participant’s program enrollment or provider offering. Institutions can add fields for the preferences and criteria they want to compare, such as field of study, channel, availability, skills, or location. These comparison attributes are configurable rather than a fixed mentoring-profile field model.",tags:["MentoringProfile"],docs:["A mentoring profile record helps connect a mentee with a suitable mentor. When creating the record, a facilitator selects the participant’s Contact. For Related Record, the facilitator selects either the program enrollment or provider offering associated with that contact. Creating a mentoring profile does not create the user profile required for portal access.","Institutions can create and add fields to the mentoring profile record page based on their matching requirements. Documented examples include industry or field of study, virtual or in-person channel, days and times available, skills, and location. These fields can be shown in the Mentor Comparison screen flow and used to identify similarities between participants. Lookup Relationship, Master-Detail Relationship, and System fields aren’t supported for mentoring participant comparison.","A record-triggered flow can create or update mentoring profile records after mentors and mentees complete an assessment. The flow can retrieve assessment question responses, determine whether the profile is for a mentor or mentee, and map response values into configured profile fields. It associates a mentee profile with a program enrollment or a mentor profile with a provider offering. Existing profiles can be updated instead of creating duplicate profiles."],connections:[{"planet":"records","desc":"Profiles reference person account records"}]},
    {id:"mentor-matching",name:"Mentor Matching",icon:"\u{1F916}",desc:"Mentor Matching in Education Cloud combines assessment responses, mentoring profiles, provider offerings, and a configurable screen flow. Facilitators can select and compare up to three potential mentors using institution-defined profile fields. Matching fields can display checkmarks when values align, and Einstein Mentoring Summaries can optionally provide summaries and similarity scores. The selected mentor is assigned as the Provider for the mentee’s benefit assignment.",tags:["MentoringProfile"],docs:["Mentor and mentee assessments collect information that supports matching. Submitted responses are saved in records related to a program enrollment, enabling facilitators to review a mentee’s needs and the support that mentors can provide. Institutions create separate assessments for mentors and mentees. Assessment responses can also populate configurable mentoring profile fields through a record-triggered flow.","The Mentoring: Match Mentor and Mentee screen flow can be cloned and configured for an institution’s comparison process. Administrators select which mentoring profile fields appear during mentor selection, which fields appear in the comparison view, and which fields indicate a match. Facilitators launch the flow from a mentee’s benefit assignment, select up to three providers to compare, and review the selected mentor before completing the assignment. A configured Assign a Provider button makes the flow available from the benefit assignment record page.","Einstein Mentoring Summaries can be added to the comparison flow when the required feature and permissions are enabled. The comparison view can generate mentor and mentee overviews, a prompt response, and a similarity score based on selected profile fields. The similarity score is a vector distance calculation that indicates potential matches and is not itself the assignment. Generative AI output must be reviewed for accuracy and safety."],connections:[]},
    {id:"benefit-assignment",name:"Benefit Assignment & Tracking",icon:"\u{1F4E6}",desc:"Benefit Assignment & Tracking in Education Cloud represents delivery of a mentoring benefit to a mentee. Enrollment in a mentoring program creates a benefit assignment, which facilitators use to assign or change the mentor serving as Provider. The record page brings together participant details, mentoring activities, alerts, action plans, interaction summaries, assessments, and related activity. Mentoring sessions can be scheduled as appointments, while benefit and outcome records support ongoing tracking.",tags:["Benefit","BenefitAssignment"],docs:["When a mentee enrolls in a mentoring program, Education Cloud creates a benefit assignment record. The Mentoring home page includes an Unmatched Benefit Assignment list view for assignments where Provider is unspecified. A facilitator can match the mentor and mentee by setting Provider on the benefit assignment to the selected mentor’s contact value. The provider can be assigned through the comparison flow or changed manually from the benefit assignment details.","The benefit assignment record page supports ongoing management of the mentoring relationship. It can show the mentee and mentor names and contact information, a Timeline of mentoring activities, and actions for creating alerts, notes, tasks, and email. Related lists can expose Record Alerts, Action Plans, Interaction Summaries, assessments, and other supporting records. Interaction Summaries can capture structured notes for meetings and sessions between mentors and mentees.","Mentoring sessions can be scheduled as appointments through Education Cloud appointment management. Timeline provides a chronological history, while Record Alerts identify items that require attention and Action Plans organize tasks for participants or staff. Outcome Management can define, measure, and evaluate the impact of mentoring programs. These outcomes can be tracked as student success metrics."],connections:[{"planet":"success","desc":"Mentoring outcomes feed student success metrics"}]}
  ],
  dataFlow: ["Create the mentoring Program and define its related mentoring Benefits.","Enroll mentees and register mentors as benefit providers.","Create mentoring profiles linked to Contacts and the relevant Program Enrollment or Provider Offering.","Collect assessment responses and compare potential mentors with the mentee.","Set Provider on the Benefit Assignment to the selected mentor’s contact value.","Schedule mentoring sessions as appointments and evaluate outcomes as student success metrics."],
  connections: [{"planet":"records","desc":"Mentor/mentee profiles linked to person records"},{"planet":"success","desc":"Mentoring outcomes tracked as success metrics"},{"planet":"appointments","desc":"Mentoring sessions scheduled as appointments"}]
},

alumni: {
  packages: ["educationcloud"],
  name: "Alumni & Advancement",
  icon: "\u{1F3C5}",
  color: "#ec4899",
  description: "Alumni & Advancement in Education Cloud centralizes alumni relationships, engagement, volunteering, donor outreach, fundraising, gifts, and commitments after graduation. Alumni status and institutional roles are represented through Person Accounts and Constituent Role records, while Experience Cloud supports alumni profiles, directories, giving experiences, and volunteer participation. Data 360, Alumni Engagement Metrics, Alumni Insights, Fundraising rollups, advancement dashboards, and giving reports provide insight into philanthropic and non-philanthropic engagement, while Accounting Subledger prepares contributed-fund data for institutional accounting. The Donor Engagement Agent captures donor meeting notes as Interaction Summaries and creates follow-up tasks, helping advancement teams preserve relationship intelligence and manage outreach.",
  components: [
    {id:"alumni-engagement",name:"Alumni Engagement",icon:"\u{1F465}",desc:"Alumni Engagement gives institutions a centralized way to maintain alumni information and understand how former students remain involved. Education Cloud models alumni as Person Accounts and uses Constituent Role records to track their current and past relationships with the institution. Experience Cloud supports alumni profiles and a searchable directory, while Volunteer Management supports opportunities, sign-up, hour tracking, and impact reporting. Data 360, Alumni Engagement Metrics, Alumni Insights, and the Donor Engagement Agent help staff evaluate engagement and manage personalized outreach.",tags:["Account"],docs:["The Alumni Relations app centralizes alumni information and activities for alumni coordinators and managers. Staff can review account and profile details, education and employment history, relationships, life events, alerts, cases, and interest tags from an alumni record. Education Cloud uses Person Accounts to represent alumni and Constituent Role records to track their association with the institution over time. The Alumni Relations Console provides a home page where staff can review alumni information and identify engagement opportunities.","An Experience Cloud site can provide alumni with profile pages and a searchable directory. Alumni can populate personal, educational, and professional information, make their directory profile public, and connect with other alumni. Permission sets, profiles, sharing sets, system permissions, and audiences control access to alumni pages and records. Volunteer Management can extend the community with volunteer opportunities that users can browse, search, and join, while staff track applications, schedules, hours, and impact.","Alumni Engagement Metrics combines Data 360 and Einstein generative AI to track philanthropic and non-philanthropic activities and translate them into engagement insights. Its flows can summarize events and activities, personal engagement, meaningful volunteer impact, philanthropic contributions, or overall engagement. Alumni Insights reports alumni counts, portal profile adoption, open alerts and cases, occupations, and learning achievements. The Donor Engagement Agent converts raw donor meeting notes into Interaction Summaries and can create follow-up tasks and reminders for gift officers."],connections:[{"planet":"records","desc":"Alumni are former students with person records"},{"planet":"experience","desc":"Alumni portal for community engagement"}]},
    {id:"gift-management",name:"Gift Management",icon:"\u{1F381}",desc:"Gift Management in Education Cloud supports gift entry, processing, allocation, acknowledgment, refund, and donor support activities. GiftTransaction records track one-time donations and installments that fulfill gift commitments, while related GiftTransactionDesignation records allocate transaction amounts to funds. Gift Entry and Gift Entry Grid support individual and batch processing, including soft credits, campaigns, and outreach source codes. Fundraising rollups, donor profiles, acknowledgments, tax receipts, and Accounting Subledger support reporting, stewardship, and accounting processes.",tags:["GiftTransaction","GiftTransactionDesignation"],docs:["Gift transactions track donations received as one-time gifts or as installments that fulfill commitments. A transaction can be attributed to a donor, campaign, outreach source code, and gift commitment. Fundraising can create GiftTransaction records automatically when users process gift entries or schedule gift commitments, and users can create them manually when necessary. Transaction statuses support the processing of unpaid, pending, paid, failed, canceled, written-off, and fully refunded gifts.","Gift designations allocate incoming donations to funds established for specific purposes. GiftTransactionDesignation records store the allocation for a transaction, and allocations can be expressed through an amount or percentage. If transaction allocations total less than 100%, Fundraising assigns the remainder to the org-wide default designation. Gift transaction designations are the source of truth for updating designation rollups.","Users can enter gifts individually or collect them in a gift batch for processing together. Gift Entry and Gift Entry Grid can capture donor details, payment information, commitments, campaigns, outreach source codes, designations, and soft credits. Batch dry runs validate data without creating records, allowing users to correct errors before processing. Processing creates or updates gift transactions and can create related designation and soft-credit records.","Salesforce DocGen uses customizable templates to generate individual or batch gift acknowledgments and tax receipts. Donor Giving Summary and Gift Designation rollups expose giving history, recurring gifts, soft credits, pledged revenue, and designation metrics. Accounting Subledger consolidates fundraising data between Education Cloud and an external accounting system so contributed funds can be reflected in institutional accounting. Refund records preserve transaction history while updating the refunded and current amounts on the related gift transaction."],connections:[{"planet":"financials","desc":"Gift funds connect to institutional finance"}]},
    {id:"gift-commitments",name:"Pledges & Commitments",icon:"\u{1F4DD}",desc:"Pledges & Commitments manages promised monetary and in-kind gifts in Education Cloud. GiftCommitment records support one-time pledges, multipayment gifts, and open-ended recurring gifts, while GiftCommitmentSchedule records define recurring or custom transaction schedules. Automated processing updates upcoming installments, creates recurring transactions when configured, and changes commitment status according to schedules and transaction results. Users can modify, pause, resume, or close commitments while retaining a record of relevant changes.",tags:["GiftCommitment","GiftCommitmentSchedule"],docs:["A gift commitment records a donor's promised contribution and can be associated with a campaign, opportunity, designation, or soft credit. Users select a Recurring schedule type for gifts paid as a set amount on a repeating schedule or Custom for nonrecurring gifts paid in one or more installments. In-kind donations are also represented as gift commitments, with fields for expected asset transfer and value information. Gift commitments can therefore represent recurring gifts, multipayment pledges, inbound grants, and non-monetary contributions.","Gift commitment schedules determine when and how transactions occur. Recurring schedules use start and optional end dates, a transaction period and interval, a transaction day when applicable, a transaction amount, and payment information. Custom schedules support individual installments and can include multiple scheduled payments. When users create or update schedules from the gift commitment page, Fundraising automatically creates or updates the associated gift transactions.","Gift commitment processing identifies the next installment and updates the Next Transaction Date, Next Transaction Amount, current schedule, effective period, and effective interval. Depending on configured settings and transaction history, processing can update a commitment to Active, Paused, Lapsed, Failing, or Closed. Users can upgrade or downgrade a recurring commitment, change its dates or payment method, and pause or resume its schedule. Changes are captured in the Gift Commitment Change Attribution Log, including the campaign and outreach source code associated with the change."],connections:[]},
    {id:"fundraising",name:"Fundraising Campaigns",icon:"\u{1F4C8}",desc:"Fundraising Campaigns organizes donor outreach and connects fundraising activity with campaigns, opportunities, gifts, and commitments. Outreach source codes distinguish the messages and channels used within a campaign and help attribute resulting donations. Campaign and outreach rollups summarize response, donor, gift-count, and gift-amount metrics for evaluating performance. Data Cloud segmentation, RFM scoring, advancement dashboards, and giving reports help teams identify audiences and refine future outreach.",tags:["Campaign"],docs:["Fundraising campaigns use standard Salesforce campaigns and can be enhanced with outreach source codes. An institution can create separate source codes for mailings, digital advertising, events, or other appeals within the same campaign. Users associate the applicable source code with a gift entry or gift transaction, and the related campaign is populated from that code. Outreach source code URLs can include configured UTM parameters to track digital sources, media, and campaigns.","Campaigns and outreach source codes support structured audience and message management. Staff can create source codes individually or in bulk, record message titles and content, and assign interest tags that describe campaign or audience interests. Donor and partner data from different sources can be mapped to Data Cloud and used to segment campaign audiences. Scoring frameworks such as Recency, Frequency, and Monetary Value help identify donors whose giving behavior fits particular campaigns or outreach programs.","Outreach Summary rollups expose campaign and source-code metrics such as gift count, response rate, total gift transaction amount, donor counts, and average gift amounts. Data Processing Engine definitions calculate and refresh fundraising summaries and actionable lists, and scheduled flows can automate those updates. Fundraising Strategy and Donor Engagement provide campaign and engagement views for planning and managing outreach. Advancement dashboards and giving reports complement these rollups by helping staff evaluate campaign performance and giving activity."],connections:[{"planet":"analytics","desc":"Giving analytics and advancement dashboards"}]}
  ],
  dataFlow: ["Track alumni status and institutional roles on Person Account and Constituent Role records.","Engage alumni through the Experience Cloud portal for profiles, giving, directories, and volunteering.","Capture gifts, allocations, commitments, schedules, campaigns, and outreach source codes in Fundraising.","Use the Donor Engagement Agent to save donor meeting notes as Interaction Summaries and create follow-up tasks.","Prepare contributed-fund data for institutional finance with Accounting Subledger.","Analyze engagement and giving with Alumni Engagement Metrics, Alumni Insights, advancement dashboards, rollups, and giving reports."],
  connections: [{"planet":"records","desc":"Alumni status tracked on person records"},{"planet":"financials","desc":"Gift funds connect to institutional finance"},{"planet":"agentforce","desc":"Alumni engagement agent manages outreach"},{"planet":"experience","desc":"Alumni portal for giving and volunteering"},{"planet":"analytics","desc":"Advancement dashboards and giving reports"}]
},

appointments: {
  packages: ["educationcloud"],
  name: "Appointments",
  icon: "\u{1F4C5}",
  color: "#14b8a6",
  description: "Appointments provides Education Cloud with a centralized, self-service system for scheduling and managing learner meetings across institutional services. Learners can view staff availability and schedule in-person, phone, or virtual appointments, while staff can schedule on their behalf from student person records; separate drop-in waitlists support walk-in check-ins before a service resource accepts and creates the scheduled appointment. Appointment scheduling supports student success and mentoring sessions, and advising appointments can address advising required before registration. Appointment topics, cases, success teams, service resources, service territories, engagement channels, and shifts determine which staff, channels, locations, and times are available.",
  components: [
    {id:"appointment-scheduling",name:"Appointment Scheduling",icon:"\u{1F4C5}",desc:"Appointment Scheduling provides centralized appointment booking for learners and staff in Education Cloud. Learners can view appointment options and schedule meetings through an Experience Cloud site, while staff can schedule on a learner's behalf from the learner's person account record. Appointment topics, engagement channels, service territories, cases, success teams, and service resources determine the available scheduling choices. Scheduled meetings can support advising, student success, recruitment, and mentoring processes.",tags:["ServiceAppointment"],docs:["Education Cloud uses Salesforce Scheduler and the EDUScheduler Omniscript to provide appointment scheduling. Learners access scheduling through an Experience Cloud site, while staff use the Staff Appointment Scheduling component on the learner's person account record. A learner must have an existing related case before the learner or a staff member can schedule an appointment. The My Appointments Header component provides a workflow in which learners select a success team, advisor, topic or subtopic, and then check availability before choosing a time slot.","Work Type Groups and Work Types represent appointment topics and their scheduling details. Work Type Groups can form a topic hierarchy, but users select only a topic at the lowest level; Work Types define details such as estimated duration and appointment category. Engagement Channel Types identify channels such as in-person or phone, and Service Territories group appointments by characteristics such as location or department. Success Team records connect case record types and predefined case teams to appointment availability, including whether learners can self-schedule with a support pool.","Education Cloud supports in-person, phone, and virtual appointments. Staff can schedule appointments with assigned or otherwise available teams from a learner's record, while learners generally schedule with staff or teams available through their cases and active Success Team records. Automatic Resource Assignment can assign a service resource according to availability and an appointment assignment policy, or allow learners to choose an advisor when the Success Team resource assignment type supports both options. Service Appointments represent the appointments created by these scheduling processes."],connections:[{"planet":"enrollment","desc":"Advising appointments precede course registration"},{"planet":"success","desc":"Advising sessions support student success"}]},
    {id:"staff-availability",name:"Staff Availability",icon:"\u{1F464}",desc:"Staff Availability determines when and where service resources can accept appointments in Education Cloud. Shifts, service territories, appointment topics, and engagement channels define the time slots presented to learners and staff. Advisors can use Manage Availability to maintain working hours, recurring availability, and time off for themselves or colleagues. Case team roles and predefined case teams can further limit the topics available for a selected staff member.",tags:["ServiceResource","ServiceTerritory"],docs:["Education Cloud uses shifts from a staff member's service territory to determine available appointment times. Although operating hours are required when creating service territories, Salesforce Scheduler for Education Cloud uses shifts rather than operating hours to calculate staff availability. A shift can cover one or more service territories, appointment topics, and engagement channels. This structure supports patterns such as on-campus advising on selected days and virtual appointments on other days.","The Manage Availability component lets authorized users add availability for a service resource and select a related service territory whose membership dates overlap the availability period. Users specify the time slot type, availability status, start and end times, appointment topics, engagement channels, and recurrence. Selecting Filter topics by case team roles limits topics according to the service resource's roles in predefined case teams. Roles created through an individual addition to a learner's case team aren't considered by that filter.","Service Resources represent staff members who can be assigned to appointments, and Service Territory membership connects them to the locations or organizational groupings where they work. A staff member can have one primary territory and multiple secondary territories. Deactivating a Service Resource removes the staff member from appointment scheduling, and deactivating the related user also deactivates the Service Resource. Education Cloud recommends reviewing created shifts on the staff member's profile so that scheduled and drop-in time slots are accurate."],connections:[]},
    {id:"waitlist-management",name:"Waitlist & Walk-ins",icon:"\u{23F3}",desc:"Waitlist & Walk-ins supports in-person drop-in consultations through waitlists associated with available service resources. Front-office staff can create a waitlist and generate a QR code that learners scan to check in. Learners can monitor their check-in status and queue position while waiting. A service appointment becomes visible only after a service resource accepts the check-in.",tags:["ServiceAppointment"],docs:["Drop In Appointments provides lobby management for learners who arrive for an in-person consultation without a scheduled meeting. Front-office staff create a waitlist for available service resources and generate a QR code that links to a waitlist check-in page. Learners scan the code, select a topic, and add themselves to the waitlist. The related shift must include an in-person engagement channel and drop-in appointment topics for drop-in availability to appear.","On the learner portal, learners can check the status of their check-ins and their position in the queue. Service resources receive notice of the check-in and can accept the drop-in appointment while the learner waits. When a service resource accepts a check-in, the learner can view the resulting scheduled appointment on the Upcoming appointments tab. The waitlist check-in is therefore distinct from the Service Appointment that results after acceptance.","Drop-in setup requires the Drop In Appointment setting, appointment categories, relevant Work Types, a Service Territory, and appropriate sharing access for the Waitlist object. Administrators add the QR Code component to the waitlist record page and configure a learner portal page with the Scheduler/DropInAppointment Omniscript. The generated target URL includes the waitlist record ID so that the QR code directs the learner to the correct queue. Salesforce uses shifts, including the absence of shifts, to determine staff availability rather than automatically accounting for holidays, weekends, or time off."],connections:[]},
    {id:"virtual-appointments",name:"Virtual Appointments",icon:"\u{1F4F9}",desc:"Virtual Appointments enables learners and staff to meet through audio and video from Education Cloud appointment experiences. Education Cloud supports virtual calls with the Amazon Web Services Chime SDK after Salesforce Scheduler is configured. Staff join AWS Chime calls as moderators, while learners join as regular attendees. Virtual appointment access is controlled by the appointment status and permitted join times.",tags:["ServiceAppointment"],docs:["To use Virtual Calls, administrators configure Salesforce Scheduler, enable Video Calls, connect Amazon to Salesforce, and deploy the required AWS services. They create a named credential for the AWS Chime callout endpoint and add a dedicated Virtual Calls page to the Experience Cloud site. Appointment data must also include the video type before video appointments are configured. The Video Call component can be added to the app utility bar so that staff can join calls easily.","When staff members join an AWS Chime call, they receive the moderator role and can perform actions such as muting all participants or ending the meeting for everyone. Learners join as regular attendees through the portal. Education Cloud allows learners to join when the Service Appointment status is In Progress or Scheduled and the current time falls between the Earliest Start Permitted and Due Date values. For video calls that use external services instead of AWS Chime, Education Cloud displays information from the Appointment Booking URL field.","Meeting hosts should inform attendees if a meeting will be recorded and explain how the recording will be used and shared. Hosts should also provide options to participate without recorded video or audio, including attending without video or audio and using text chat for questions. These practices accompany the technical setup for virtual appointments and address attendee privacy and participation needs."],connections:[{"planet":"mentoring","desc":"Mentoring sessions use appointment scheduling"}]}
  ],
  dataFlow: ["Configure appointment topics, engagement channels, service territories, success teams, service resources, and shifts.","Reference the learner's person record and related case, including advising required before registration when applicable.","Present eligible staff, channels, locations, and time slots through the Education Cloud scheduling experience.","Book the appointment for student success, advising, or mentoring, or check the learner into a separate drop-in waitlist.","Create the Service Appointment after scheduling or after a service resource accepts a drop-in check-in.","Track the appointment and let eligible attendees join the configured virtual call when applicable."],
  connections: [{"planet":"enrollment","desc":"Advising required before registration"},{"planet":"records","desc":"Appointments reference student person records"},{"planet":"success","desc":"Advising appointments support student success"},{"planet":"mentoring","desc":"Mentoring sessions use appointment scheduling"}]
},

analytics: {
  packages: ["educationcloud"],
  name: "Education Analytics",
  icon: "\u{1F4CA}",
  color: "#f97316",
  description: "Education Analytics uses CRM Analytics in Education Cloud to create, customize, and embed dashboards and institutional key performance indicators in app consoles for directors, recruiters, reviewers, admissions officers, and advisors. It provides role-specific insights into recruitment, admissions, learner engagement, academic activity, advisor efficiency, and student success. Its connected scope includes recruitment funnel dashboards, revenue and financial aid analytics, advancement and giving dashboards, and Agentforce performance monitoring. Administrators configure permissions, enable the analytics app, refresh its data, and place dashboards on the appropriate Education Cloud console pages.",
  components: [
    {id:"director-insights",name:"Director Insights",icon:"\u{1F3E2}",desc:"Director Insights is the Student Success dashboard for directors in Education Cloud. It provides an institutional view of student performance and advisor activity, performance, and efficiency across the Institutional Overview, Student Success, and Advisor Insights pages. Directors can filter data by academic term and compare it with a previous period to evaluate progress. The dashboard is distinct from the Admissions and Recruitment Insights dashboard used for recruitment and admissions.",tags:[],docs:["The Director Insights dashboard helps Student Success directors monitor institutional-level performance annually. Its Institutional Overview page shows metrics such as total students, students enrolled in advisor services, the advisor-to-student ratio, average cumulative grade point average, and changes from a previous period. It also presents multiyear institutional performance based on enrollment, total students, and average cumulative grade point average.","The Student Success page covers alerts, care plans, and appointments. Directors can examine average alert resolution time, distributions of alerts and care plans by status and case record type, students without advisor appointments, and overall appointment utilization and cancellation rates. The Advisor Insights page identifies top- and least-performing advisors and shows each advisor's utilization and cancellation rates for the selected academic year.","Administrators can add the CRM Analytics Dashboard component to the Student Success director console in Lightning App Builder and select the Student Success dashboard. The console can also include Education Students Without Success Team, Education Directors Open Alerts, and Education Advisors List dashboards on separate tabs. Administrators activate the page for the Student Success app and assign it to the profiles that need access."],connections:[]},
    {id:"recruitment-analytics",name:"Recruitment Analytics",icon:"\u{1F4C8}",desc:"Recruitment Analytics provides CRM Analytics dashboards for recruitment and admissions roles in Education Cloud. Recruitment Insights focuses on the candidate pipeline, requests for information, and lead sources, while Admissions Insights focuses on application volume, reviews, decisions, and admission efficiency. The separate Admissions and Recruitment Insights dashboard gives directors an overall summary of both pipelines. These dashboards support recruitment funnel analysis and can be embedded in role-appropriate Recruitment & Admissions consoles.",tags:[],docs:["The Recruitment Insights dashboard helps recruiters analyze pipeline health and the status of requests for information. It shows the count of applications in each pipeline stage, the overall count and status distribution of RFIs, and the number of applications generated by each lead source. Recruiters can use these insights to prioritize prospects and schedule appointments effectively.","The Admissions Insights dashboard helps admissions officers monitor the health of the admissions pipeline. It presents application counts and statuses, application review counts and stages, admission and yield efficiency, incomplete applications, and applications awaiting a decision. Filters for application type and application creation date can be combined with period comparisons to evaluate progress.","The Admissions and Recruitment Insights dashboard is designed for directors and combines recruitment and admissions KPIs. It summarizes applications by status, total applications, application reviews by status, application decision outcomes, yield and admission efficiency, RFI responses, and leads by source. In Lightning App Builder, administrators can place Recruitment and Admissions Insights on the Recruitment & Admissions director console, while the recruiter console uses Recruitment Insights and the admissions console uses Recruitment and Admissions Insights."],connections:[{"planet":"recruitment","desc":"Recruitment funnel data feeds analytics"}]},
    {id:"student-success-metrics",name:"Student Success Metrics",icon:"\u{1F3C6}",desc:"Student Success Metrics uses Education Cloud analytics to monitor learner support, academic progress, advisor activity, and program performance. Advisor Insights covers alerts, care plans, and appointments, while Learning Programs and Course Insights analyzes applicants, enrolled students, courses, faculty, and departments. These metrics help advisors identify items requiring attention and help institutions evaluate learning programs and resource allocation. Role-appropriate dashboards can be placed in Student Success app consoles.",tags:[],docs:["The Advisor Insights dashboard contains Alerts, Care Plans, and Appointments pages. Advisors can review caseload and alert counts, active alerts, average case resolution time, care plans that are overdue or on track, appointment totals, and appointment utilization and cancellation rates. Charts also distribute alerts, care plans, and appointments by criteria such as case record type, status, channel, and topic type.","Learning Programs and Course Insights provides broader academic and program metrics. Its Applicants tab includes total applications, acceptance and admission rates, application pipeline status, program and term comparisons, and diversity, equity, and inclusion insights. The Enrolled Students and Faculty tabs cover enrollment counts, registered courses, learning achievements, grades, course availability, waitlists, faculty allocation, and departmental performance.","Administrators configure Education Analytics with Education Cloud Full Access and CRM Analytics for Education Cloud Admin permissions. They can schedule a refresh of the Education Analytics app or manually run the SFDC_LOCAL connection and the documented Education Analytics recipes in Analytics Studio. Access to view or manage analytics is assigned to additional users after the app is enabled."],connections:[{"planet":"success","desc":"Success tracking data powers analytics"}]}
  ],
  dataFlow: ["Enable Education Analytics and assign the required CRM Analytics permission sets.","Refresh Education Analytics data from Education Cloud and its connected recruitment funnel records.","Analyze recruitment funnel dashboards and student success KPIs in CRM Analytics.","Review connected revenue and financial aid analytics and advancement and giving dashboards.","Monitor Agentforce performance alongside institutional analytics.","Embed the appropriate dashboards in Education Cloud app consoles for each role."],
  connections: [{"planet":"recruitment","desc":"Recruitment funnel dashboards"},{"planet":"financials","desc":"Revenue and financial aid analytics"},{"planet":"alumni","desc":"Advancement and giving dashboards"},{"planet":"agentforce","desc":"Agent performance monitoring"}]
},

agentforce: {
  packages: ["educationcloud"],
  name: "Agentforce",
  icon: "\u{1F916}",
  color: "#a855f7",
  description: "Agentforce in Education Cloud applies generative AI to recruitment, admissions, student success, student financials, financial aid, and advancement workflows. Education-specific agents and subagents answer questions, create or update supported records, summarize advising and donor interactions, recommend goals or follow-up, and coordinate selected actions using configured Knowledge, CRM records, and Data 360 data. Institutions control behavior through permissions, sharing, flows, search retrievers, prompt templates, messaging channels, identity verification, and escalation paths. Digital Wallet consumption data, audit information, agent usage metrics, and analytics dashboards support operational monitoring.",
  components: [
    {id:"recruitment-agent",name:"Student Recruitment Agent",icon:"\u{1F4E3}",desc:"The Student Recruitment Agent in Education Cloud helps prospective students and families learn about an institution, its programs, admissions processes, and campus offerings. Its subagents answer recruitment and admissions questions, create Academic Interest records, register users for campus events, and start admissions applications. Knowledge articles, Learning Program data, Academic Term data, and Program Term Application Timeline data ground its responses and actions. Institutions can configure authenticated and unauthenticated experiences, human escalation, permissions, and Experience Cloud deployment.",tags:[],docs:["The Student Recruitment Agent includes subagents for Admissions and Enrollments FAQ, Admissions Application, Campus Tours, Visits, and Events Registration, and Request for Information. These subagents use actions such as Answer Questions with Knowledge, Get Learning Program Data, Create Admissions Application, and Create Academic Interest. They support recruitment outreach automation, admissions and application-status questions, application initiation, and requests for recruiter follow-up. An escalation subagent can redirect unanswered conversations to a human representative and can include the Create Inquiry action.","Institutions create knowledge articles covering learning programs, support programs, application processes, and campus and support information. The agent can also use a Learning Program data stream, a hybrid search index, and configured data retrievers and prompt templates. Administrators must grant the agent appropriate object, field, system, and sharing access through a customized Education Cloud AI Agent Access permission set. Public knowledge actions should reference only information that the institution is comfortable making available without authentication.","Education Cloud provides separate Student Recruitment templates for authenticated and unauthenticated users. Unauthenticated deployment requires cloning and configuring specified flows to run in System Context Without Sharing - Access All Data when that configuration aligns with the institution's security model. The agent can be connected to an Experience Cloud site through the appropriate employee or service agent channel. Digital Wallet provides near real-time consumption data for applicable agent actions and conversation usage."],connections:[{"planet":"recruitment","desc":"Automates recruitment outreach sequences"}]},
    {id:"success-agent",name:"Student Goals Agent",icon:"\u{1F31F}",desc:"The Student Goals Agent recommends campus resources to learners, including courses, support programs, and involvement groups, based on learner information and assessment insights. These recommendations help learners discover academic and co-curricular opportunities aligned to their goals, while advising case summaries and proactive next-best actions are handled separately by Student Advising Topics in Agentforce.",tags:[],docs:["Student Advising Topics in Agentforce includes the Student Advising and Campus Engagement subagent with Summarize Advising Case, Find Advising Cases, and Find Campus Resources actions. Advisors can use it to understand advising cases, answer student questions about policies and campus resources, and identify next-best actions. Knowledge articles ground policy answers, while an Einstein search retriever finds campus resources from configured data streams. Institutions must apply access controls that comply with their policies and data privacy requirements.","The Student Goals Agent includes Self Serve Student Goals and Advising Assist Student Goals subagents. It can suggest personalized SMART goals, create goals with target completion dates, and find campus resources that support those goals. The EDU Cloud: Get Learner Details flow can ground recommendations in person traits, competencies, affinities, involvement groups, first-generation status, academic profile data, and assessment results. Institutions must customize the flow to use the data they collect and clearly communicate that recommendations are guidance rather than a substitute for human advisors, mentors, or counselors.","For at-risk student identification, the Course Operations Agent can create at-risk reports, generate course offering participant insights, create record alerts, and create Slack channels for coordinated support. Its Student Risk Report subagent uses configured course-score calculations, categorization, and course participation data to identify learners who may need intervention. Faculty can use these capabilities directly in Slack to review risk factors and collaborate with advising case team members. Institutions should define their own risk criteria, escalation protocols, and safety workflows."],connections:[{"planet":"success","desc":"AI advising surfaces at-risk students"}]},
    {id:"financials-agent",name:"Student Financials Agent",icon:"\u{1F4B0}",desc:"The Student Financials Agent in Education Cloud helps students retrieve account balances and understand their fees. Its Student Account Management and Student Fee Management subagents provide balances, fee breakdowns, fee explanations, and account-history details. The agent retrieves fee information by querying Salesforce objects used by Student Financials rather than requiring financial-aid data in Data 360. The separate Financial Aid Agent uses financial-aid Data Model Objects in Data 360 to answer personalized questions about aid status, requirements, awards, costs, disbursements, and academic progress.",tags:[],docs:["The Student Financials Agent uses Get Account Balance, Query Records, Get Record Details, Get Fee Details, and Get Fee Breakdown actions. To retrieve fee information, it queries Academic Term, Academic Term Enrollment, Academic Order, Order Product, Billing Schedule, Credit Memo, Invoice, and Invoice Line records. Administrators configure the EDU Student Financials: Get Fee Details for Academic Order flow and grant students the required Education Cloud, Student Financials, pricing, flow, and Experience Cloud permissions. Sharing settings and sharing sets control access to account and academic term enrollment records.","The Financial Aid Agent has a distinct data architecture. External financial-aid management system data is ingested and mapped to financial-aid Data Model Objects in Data 360, and that data grounds the Financial Aid Agent and powers the financial aid Lightning web components. The agent can answer questions about financial aid status, award details, estimated cost of attendance, disbursement dates, and satisfactory academic progress. Missing or incomplete DMO records can prevent accurate student-specific answers.","Before returning personalized financial aid information, the Financial Aid Agent verifies identity. Authenticated students can bypass email verification, while unauthenticated prospects must complete one-time password verification against a Person Account with a valid contact ID and email. The agent provides factual information but doesn't give financial advice, accept or decline awards, submit documents or applications, or change financial aid packages. Administrators configure the Financial Aid Data Graph, verification actions, agent filters, permissions, enhanced event logs, and Experience Cloud messaging deployment."],connections:[{"planet":"financials","desc":"Handles billing and aid inquiries"}]},
    {id:"alumni-agent",name:"Donor Engagement Agent",icon:"\u{1F3C5}",desc:"The Donor Engagement Agent in Education Cloud helps major giving officers preserve donor intelligence and automate advancement follow-up. It converts raw donor meeting notes into structured Interaction Summaries and creates related tasks and reminders. The agent uses the Donor Meeting Notes and Donor Task Management subagents with standard record, interaction, and task actions. It can also be connected to Slack so gift officers can record meeting notes and create follow-up work without changing applications.",tags:[],docs:["The Donor Engagement Agent template includes Donor Meeting Notes, Donor Task Management, and Agent Router subagents. Donor Meeting Notes uses the Prepare Donor Meeting Notes prompt template and actions such as Identify Record by Name, Query Record, Create Interaction, and Create Interaction Summary. Donor Task Management uses actions including Create a To-Do, Extract Fields and Values From User Input, Update Record, and Get Record Details. Together, these capabilities support alumni and donor engagement automation by preserving meeting context and translating next steps into Salesforce records.","Administrators enable Fundraising and Interaction Summaries, activate the Prepare Donor Meeting Notes prompt template, and create an agent from the Donor Engagement template. Access is controlled through the applicable Fundraising, Agentforce for Fundraising Access, and Prompt Template permissions. After activation, the agent can be added to Slack for advancement staff. Gift officers can then submit raw notes, review the generated interaction summary, save it to the donor record, and create follow-up tasks with requested due dates.","The Donor Engagement Agent is distinct from the Engagement Visualization Lightning web component and Alumni Engagement Metrics. Engagement Visualization shows Data 360 calculated insights and Einstein generative AI prompt responses grounded in CRM and Data 360 data. Alumni Engagement Metrics uses that component to summarize experiential, communications, volunteerism, and philanthropic engagement for alumni and supporters. Institutions can use those metrics alongside the Donor Engagement Agent, but the visualization capability isn't itself an alumni agent."],connections:[{"planet":"alumni","desc":"Manages alumni outreach and engagement"}]}
  ],
  dataFlow: ["Enable Education Cloud, Einstein Generative AI, Agentforce, and the required domain features.","Assign agent, user, object, field, flow, and data-access permissions.","Configure knowledge, data streams, search retrievers, prompt templates, subagents, actions, and escalation paths.","Deploy agents through Experience Cloud messaging, employee channels, or Slack as appropriate.","Handle recruitment outreach, application-status questions, at-risk learner support, financial aid guidance, and alumni engagement follow-up.","Monitor agent consumption, audit information, usage metrics, and analytics dashboards."],
  connections: [{"planet":"recruitment","desc":"Recruitment outreach automation"},{"planet":"admissions","desc":"Application status Q&A"},{"planet":"success","desc":"At-risk student identification"},{"planet":"financials","desc":"Financial aid guidance"},{"planet":"alumni","desc":"Alumni engagement automation"},{"planet":"analytics","desc":"Agent usage metrics and dashboards"}]
},

experience: {
  packages: ["educationcloud"],
  name: "Experience Cloud",
  icon: "\u{1F310}",
  color: "#64748b",
  description: "Experience Cloud provides the secure online portal foundation for Education Cloud constituents across recruitment, admissions, student services, financial self-service, and alumni relations. The configurable Education Portal template supplies education-specific pages and components for inquiries, applications, appointments, course registration, support services, financial information, alumni profiles, and directories. Institutions use permission sets, system permissions, audiences, sharing settings, and sharing sets to tailor content and record access for applicants, students, alumni, and people with overlapping roles. Experience Builder supports page, component, navigation, and theme configuration, while supported mobile access lets learners complete selected self-service activities on the go.",
  components: [
    {id:"student-portal",name:"Student Portal",icon:"\u{1F393}",desc:"The Student Portal provides enrolled learners with a secure, self-service Education Cloud experience for academic, support, appointment, and financial activities. Students can view learning program plans, connect with success teams, enroll in support programs, manage appointments, and work with care plans, goals, benefits, tasks, and action plans. With the required Advanced Academic Operations access, the portal can also support course registration and waitlists. Institutions can add student financial and financial aid components to present balances, awards, disbursements, and related information.",tags:[],docs:["The Education Portal template includes pages and components for common student activities. Its Learning Programs area lists the portal user’s learning program plans, while Success Team and Support Programs provide access to assigned resources and available services. Student success components also let learners view advisors, post questions, check availability, schedule appointments, manage action plans, and track career and life goals. Institutions add and configure these components with Experience Builder.","Advanced Academic Operations extends the student portal with course registration, waitlists, holds management, GPA calculation, and enrollment policy enforcement. Students require the Education Cloud Advanced Academic Operations for Experience Cloud permission set license and the applicable Experience Cloud permission sets. Every feature in the Advanced Academic Operations feature set uses Business Rules Engine and its quota capacity. Administrators must enable Academic Operations and Advanced Academic Operations before granting access.","Student financials can provide a Financial Status at a Glance component showing charges, adjustments, balance due, the next due date, and payment status. Financial aid pages use a required Financial Aid Year Filter that supplies data to other financial aid components and lets users select an award year. Optional financial aid components can present highlights, applications, checklists, awards, and disbursements, and the portal can link to an external financial aid system. Administrators must configure the required permissions, sharing access, and supporting financial or financial-aid services before publishing these experiences."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.ec_set_up_an_education_portal.htm&language=en_US",connections:[{"planet":"enrollment","desc":"Course registration through the portal"},{"planet":"financials","desc":"Financial account access and payments"}]},
    {id:"applicant-portal",name:"Applicant Portal",icon:"\u{1F4CB}",desc:"The Applicant Portal supports Education Cloud recruitment and admissions self-service from registration and requests for information through application submission and tracking. Applicants can start applications, review statuses and details, complete assigned tasks, schedule appointments, and manage submitted applications. Dynamic application options are derived from active Program Term Application Timeline records and their related academic terms, learning programs, and application timelines. A separate configuration can enable parents, guardians, caregivers, and commissioned agents to apply on behalf of students.",tags:[],docs:["The Education Portal template provides Home, Applications, Requests for Information, and Appointments areas for applicants. Home displays created applications, requests for information, tasks, and appointments, while Applications lists existing applications and lets users start a new one. Applicants can raise and monitor requests for information and schedule appointments with institution staff. When an applicant registers through the learner portal, Education Cloud automatically creates a person account for that individual.","For dynamic applications, administrators add and configure the New Application and application-detail components in Experience Builder. New Application picklist values are filtered from qualifying Program Term Application Timeline records; related academic terms and learning programs must be active, and the associated application timeline must be open. Application settings can let applicants view and edit tasks before submission, submit after completing required tasks, provide a digital signature, and confirm that their information is accurate. After submission, applicants can view task details but can no longer edit them, and they can be allowed to withdraw an application.","Education Cloud also supports a dedicated applicant portal for third-party representatives. Parents, guardians, caregivers, and commissioned agents can use configured OmniStudio components to manage students whom they represent and submit applications on their behalf. Institutions should create a separate portal for this use case if they already operate a portal where applicants apply for themselves. A sharing set must grant third-party users access to the records required for their work."],connections:[{"planet":"admissions","desc":"Application tracking and document submission"}]},
    {id:"alumni-portal",name:"Alumni Portal",icon:"\u{1F3C5}",desc:"The Alumni Portal gives former learners a secure Education Cloud experience for maintaining profiles and connecting with the institution and other alumni. Alumni can populate personal information in an Alumni Profile and search public profiles through the directory. Institutions can use audiences and permission sets to present alumni-specific pages and components while also supporting people who have overlapping applicant, student, and alumni roles. This portal experience connects alumni self-service with the broader alumni relations process.",tags:[],docs:["The Education Portal template includes components designed for alumni alongside those for applicants and students. The Alumni Profile area lets portal users populate personal information to create their profiles, and the Directory provides a searchable list of public profiles. Alumni can therefore maintain a presence in the community and find other alumni from the institution. A single portal login can also serve alumni who are applying for continued learning or otherwise hold overlapping constituent roles.","Institutions can create processes and flows from templates to maintain Alumni Directory information. Staff can use current learner and alumni data to understand an alumnus’s involvement, create related alerts and activities, and monitor alumni-relations goals with KPI reports. Alumni-specific Experience Cloud components are part of a broader Education Cloud capability that gives staff a 360-degree view of learners from prospect through involved alumnus. Access to portal pages and components is controlled through the institution’s configured audiences and permissions."],connections:[{"planet":"alumni","desc":"Alumni community and giving portal"}]},
    {id:"mobile-experience",name:"Mobile Experience",icon:"\u{1F4F1}",desc:"Mobile Experience extends the Education Cloud learner portal to supported mobile devices so learners can access key self-service functions while away from a desktop. Learners can view care-plan and success-team details and schedule appointments with advisors on the go. Institutions configure and publish the same Experience Cloud site through Experience Builder, with role-based visibility determining which pages and components each user can access.",tags:[],docs:["Education Cloud student success components bring learner self-service functions into an Experience Cloud portal. On supported mobile devices, learners can view details of their care plans and assigned success teams and schedule appointments with advisors. The broader component set also supports past and upcoming appointments, advisor information, support programs, assessments, benefits, tasks, action plans, and goals. Available functions depend on the components that the institution adds and configures.","Administrators use Experience Builder to arrange portal pages, add Education Cloud components, customize navigation, and preview and publish the site. Audiences, permission sets, and system permissions work together to control page and component visibility for applicants, students, alumni, and users with overlapping roles. Portal users must have the applicable Education Cloud for Experience Cloud access and licenses, and the security model can also use organization-wide defaults and sharing sets. This configuration keeps mobile access aligned with the same role-based and record-level controls used by the rest of the portal."],connections:[]}
  ],
  dataFlow: ["Configure the Education Portal template and add the required Experience Cloud pages and components.","Assign licenses, permission sets, audiences, and sharing access for each constituent role.","Expose recruitment inquiry and event experiences and route prospects into admissions application tracking.","Enable student course-registration and financial self-service features when the required add-ons and permissions are configured.","Provide alumni profile and directory access through the alumni community portal.","Preview and publish the portal for authorized desktop and mobile users."],
  connections: [{"planet":"recruitment","desc":"Prospect inquiry and event portal"},{"planet":"admissions","desc":"Application tracking portal"},{"planet":"financials","desc":"Financial self-service portal"},{"planet":"alumni","desc":"Alumni community portal"}]
},

data360: {
  packages: ["educationcloud"],
  name: "Data 360",
  icon: "\u{1F5C3}",
  color: "#06b6d4",
  description: "Data 360 centralizes disparate student and education data for use with Education Cloud. It ingests information from institutional systems, maps source fields to a harmonized data model, and applies identity resolution to unify student person records from multiple sources. The resulting deduplicated learner profiles support calculated insights, analytics, automation, personalized experiences, and AI grounded in trusted institutional data. Education data kits accelerate implementation with packaged data streams, mappings, calculated insights, and identity resolution resources.",
  components: [
    {id:"data-consolidation",name:"Data Consolidation",icon:"\u{1F4E5}",desc:"Data Consolidation brings disparate learner and education data into a central Data 360 environment for Education Cloud. Institutions can ingest data from student information, learning management, enterprise resource planning, engagement, advancement, and campus systems. The consolidated data supports harmonization, unified learner profiles, analytics, automation, and trusted AI grounding.",tags:["DataStream"],docs:["Education Cloud uses Data 360 to connect and prepare large volumes of data from institutional systems. Student information systems can provide profiles, registrations, payments, attendance, and grades, while learning management systems can provide usage, interactions, and assessments. Enterprise resource planning systems contribute financial records, tuition and fee details, financial aid, billing, and holds. Institutions can also ingest data from systems for housing, dining, event registration, and other campus services.","Connect external sources to Data 360 and use data streams to collect and store their data. The Education data kit packages components such as data streams and calculated insights and provides bundles with prebuilt mappings to key Education Cloud data model objects. When deploying a data kit stream, administrators select the source org, bundle, data space, fields, and stream names before deployment. An Active status indicates that the deployed data streams are ready for subsequent processing."],connections:[]},
    {id:"identity-resolution",name:"Identity Resolution",icon:"\u{1F50D}",desc:"Identity Resolution links student person records from multiple data sources into unified profiles. An identity resolution ruleset contains match and reconciliation rules that determine how related source records are linked. Education Cloud data kits can provide a preconfigured ruleset, while implementations can also create rulesets for specific data sources and use cases.",tags:["IdentityResolutionRuleset","MatchRule"],docs:["The Education data kit includes an identity resolution ruleset with match and reconciliation rules for linking multiple sources of data into a unified profile. Implementations can also create a ruleset for the data platform after ingesting and mapping source records. For financial aid, the ruleset is created on the Individual object to match records from the financial aid system with Salesforce Person Accounts. After the ruleset is published and run, administrators can confirm that it produces a nonzero data consolidation rate.","Identity resolution depends on properly mapped person data. For financial aid, the Individual DMO must be populated before related email, phone, and address DMOs because those records link to the individual. The documented financial aid configuration matches records using a combination of fuzzy and exact name matching and exact normalized email matching. For calculated insights that contain the unified individual DMO, a Contact data stream must also be created and mapped for identity resolution."],connections:[{"planet":"records","desc":"Resolved identities create unified person records"}]},
    {id:"unified-records",name:"Unified Records",icon:"\u{1F464}",desc:"Unified Records represent consolidated learner identities created by linking related source records. They provide the unified learner profile that Education Cloud uses to connect information across the learner journey. Unified individual records and links can support calculated insights, engagement visualizations, analytics, and personalized experiences.",tags:["UnifiedIndividual"],docs:["Data 360 harmonizes imported institutional data into a unified learner profile. This profile gives institutions a central view for understanding and supporting current learners, engaging alumni, and preparing for future learners. Unified data can support reliable analytics and predictions, scaled automation, trusted AI grounding, and customized learner experiences. Identity resolution supplies the links between source records and the resulting unified profile.","Education Cloud components can use calculated insights related to an individual DMO, a unified individual, or a unified individual link. For example, the Engagement Visualization component can display calculated insights and generative AI prompt responses grounded in CRM and Data 360 data. Calculated insight queries can join source records through individual identity links to a unified individual. This structure enables metrics from multiple linked records to be grouped around one learner identity."],connections:[{"planet":"records","desc":"Unified records feed into person accounts"}]},
    {id:"data-mapping",name:"Data Mapping & Standards",icon:"\u{1F5FA}",desc:"Data Mapping & Standards aligns fields and objects from connected institutional sources with Data 360 data model objects. Mapping is required before imported education data can be used for segmentation, activation, analytics, or other Data 360 operations. Education-specific DMOs and data kit mappings provide a harmonized structure for learner, academic, engagement, advancement, and financial data.",tags:["DataStream"],docs:["After importing education data, administrators map it to the required Data 360 DMOs. Connecting a source allows Data 360 to access its objects and fields so that mapping sets can be created between the source and the Data 360 model. Education Cloud provides education-specific DMOs for data from learning management, student information, engagement, advancement, and enterprise resource planning systems. Harmonized DMO data can then be used to build segments, create calculated insights, and analyze key metrics.","The Education data kit supplies prebuilt mappings to key Education Cloud DMOs through bundles. Administrators must deploy fields required by mappings, along with formula fields and their source fields. When a source system uses values that differ from those expected by a DMO, a formula field on the data stream can transform the values during ingestion. Mapping the formula field instead of the original source field preserves the original value while making the ingested data compatible with Education Cloud components."],connections:[]}
  ],
  dataFlow: ["Connect institutional source systems to Data 360.","Deploy and activate data streams in the appropriate data space.","Map source objects and fields to the required data model objects.","Configure and run identity resolution rules to unify student person records.","Use unified learner profiles for insights, analytics, automation, and trusted AI grounding."],
  connections: [{"planet":"records","desc":"Identity resolution unifies student person records"}]
}

};
